INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (1, 1, 'See Clearly', 'The Signal and the Noise', 'See Clearly', 'The difference between the mental noise and the awareness underneath it', 'What have you been carrying silently that no one else can see?', 'Signal and attention', '1 of 4', '34, 50, 51', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (1, 'Adult', 1, 'See Clearly', false, 'The Signal and the Noise', 'What Are You Actually Receiving?', 'Ancient navigators had no GPS. They used stars — fixed, reliable points present even when clouds obscured them. The practice wasn''t finding new stars. It was learning to look past the clouds. Your inner wisdom is the star. This community is the practice of clearing the sky.', 'Ancient navigators had no GPS. They used stars — fixed, reliable points present even when clouds obscured them. The practice wasn''t finding new stars.', '', '', 'Your mind is a phone with 47 tabs open and notifications firing — the signal is the one tab you opened on purpose. Today: close the tabs (one breath, one thing) and hear the quiet channel underneath the noise.', 'Your mind is a phone with 47 tabs open and notifications firing — the signal is the one tab you opened on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (2, 1, 'See Clearly', 'The Stories We Carry', 'See Clearly', 'The beliefs we repeat about ourselves, and where they came from', 'What do you believe about yourself that you have never once questioned?', 'Stories and identity', '1 of 5', '5, 25, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (2, 'Adult', 1, 'See Clearly', false, 'The Stories We Carry', 'Reading the Code You Were Given', 'Many wisdom traditions say: ''A story you don''t examine will run your life.'' Not because stories are bad — but because an unconscious story is a cage you can''t see. The practice is making it visible.', 'Many wisdom traditions say: ''A story you don''t examine will run your life.'' Not because stories are bad — but because an unconscious story is a cage you…', '', '', 'The stories you tell about yourself run like an app in the background, quietly draining the battery. Today: catch one ''I''m the kind of person who…'' and ask — did I write this, or did it just install itself?', 'The stories you tell about yourself run like an app in the background, quietly draining the battery.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (3, 1, 'See Clearly', 'The Pattern Interrupt', 'See Clearly', 'The space between what happens and how we respond', 'When did you last react in a way you didn''t choose?', 'Choice and response', '1 of 3', '19, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (3, 'Adult', 1, 'See Clearly', false, 'The Pattern Interrupt', 'Finding the Gap', 'Between stimulus and response there is a space. In that space lies your freedom. This isn''t a modern idea — Stoics, Daoists, and Buddhist traditions all pointed at the same thing: the gap is where wisdom lives. We''re just now able to see it in brain scans.', 'Between stimulus and response there is a space. In that space lies your freedom.', '', '', 'Between the notification buzzing and your hand grabbing the phone there''s a half-second gap — that gap is a superpower. Today: find the buzz-to-grab gap in one habit and slot a single breath into it.', 'Between the notification buzzing and your hand grabbing the phone there''s a half-second gap — that gap is a superpower.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (4, 1, 'See Clearly', 'What Your Body Is Telling You', 'See Clearly', 'Sensation as information, arriving before thought', 'Where in your body do you feel most at ease, and where most contracted?', 'The body', '1 of 3', '24, 30', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (4, 'Adult', 1, 'See Clearly', false, 'What Your Body Is Telling You', 'Turning the Diagnostics Back On', 'In Daoist tradition the body is not separate from wisdom — it IS wisdom. Qigong, tai chi, and traditional Chinese medicine all rest on one idea: the body is an intelligent system and its sensations are a language. The West is only now catching up through neuroscience — gut-brain research, somatic therapy, interoception studies. The body has always been speaking. We are learning to hear it.', 'In Daoist tradition the body is not separate from wisdom — it IS wisdom.', '', '', 'Your body is the check-engine light your dashboard mind keeps ignoring — tight shoulders and a clenched jaw are data, not noise. Today: do a ten-second body scan before you fire back the stressful message.', 'Your body is the check-engine light your dashboard mind keeps ignoring — tight shoulders and a clenched jaw are data, not noise.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (5, 1, 'See Clearly', 'The Mirror — How We See Ourselves', 'See Clearly', 'Seeing yourself accurately, without flattery or attack', 'If you described yourself accurately — not aspirationally, not apologetically — what would you say?', 'Stories and identity', '2 of 5', '2, 25, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (5, 'Adult', 1, 'See Clearly', false, 'The Mirror — How We See Ourselves', 'Recalibrating the Lens', 'The Zen tradition has a concept of ''beginner''s mind'' — approaching even the familiar with fresh eyes. The problem with self-perception is we are the worst people to observe ourselves objectively. We''re too close. This is why community, honest relationships, and regular self-inquiry matter — they are mirrors a solo practice cannot provide.', 'The Zen tradition has a concept of ''beginner''s mind'' — approaching even the familiar with fresh eyes.', '', '', 'The front camera shows every flaw; a good friend''s photo catches you laughing — self-awareness is choosing the friend''s lens. Today: describe yourself the way someone who loves you would.', 'The front camera shows every flaw; a good friend''s photo catches you laughing — self-awareness is choosing the friend''s lens.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (6, 1, 'See Clearly', 'The Comparison Loop', 'See Clearly', 'Measuring your inside against someone else''s outside', 'Who do you compare yourself to, and what do you imagine they have?', 'Enough', '1 of 3', '20, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (6, 'Adult', 1, 'See Clearly', false, 'The Comparison Loop', 'Getting Off the Loop', 'The Daoist idea of enoughness — zúgòu — is radical in a comparison culture. Not resignation, not lack of ambition — but a genuine resting point that doesn''t require external reference. ''I know what I have. I know what I am. That is my measure.'' This is not what markets or social media want you to believe. But it is what the wellbeing evidence supports.', 'The Daoist idea of enoughness — zúgòu — is radical in a comparison culture.', '', '', 'Scrolling compares your behind-the-scenes to everyone''s highlight reel — a treadmill where you sweat and never move. Today: name one ''race'' you''re quitting and mute the feed that runs it.', 'Scrolling compares your behind-the-scenes to everyone''s highlight reel — a treadmill where you sweat and never move.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (7, 1, 'See Clearly', 'The Inner Critic', 'See Clearly', 'The voice that narrates your failures, and where it learned to speak', 'If that voice were a person, would you choose to spend time with them?', 'The inner voice', '1 of 3', '18, 32', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (7, 'Adult', 1, 'See Clearly', false, 'The Inner Critic', 'Naming the Judge', 'In Buddhist psychology the inner critic is understood as a form of internal resistance that arises precisely when we are close to genuine growth. The tradition''s response is not combat, not suppression — but recognition. ''I see you.'' The critic loses power when it is clearly named.', 'In Buddhist psychology the inner critic is understood as a form of internal resistance that arises precisely when we are close to genuine growth.', '', '', 'The inner critic is a group chat in your head that only ever roasts you — you can mute it and add a coach who''s honest but kind. Today: when the roast fires, ask ''would I say this to my best mate?''', 'The inner critic is a group chat in your head that only ever roasts you — you can mute it and add a coach who''s honest but kind.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (8, 1, 'See Clearly', 'Beneath the Surface — Emotions as Data', 'See Clearly', 'What sits underneath the emotion you noticed first', 'What were you feeling just before you got angry?', 'Emotions as data', '1 of 3', '24, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (8, 'Adult', 1, 'See Clearly', false, 'Beneath the Surface — Emotions as Data', 'Reading the Data Stream', 'The Daoist principle of flowing like water applies to emotional life: water doesn''t fight its container. It finds every crack, every passage, every opening — and it moves. Emotions blocked are like water behind a dam. They don''t disappear. They build pressure. The practice is not controlling emotions — it''s letting them flow with awareness.', 'The Daoist principle of flowing like water applies to emotional life: water doesn''t fight its container. It finds every crack, every passage, every opening — and it moves.', '', '', 'Anger is just the app icon; tap it and the real feeling opens underneath — fear, hurt, tiredness. Today: next time you''re ''grumpy'', open the icon and read what''s actually inside.', 'Anger is just the app icon; tap it and the real feeling opens underneath — fear, hurt, tiredness.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (9, 1, 'See Clearly', 'The Wounds We Carry', 'See Clearly', 'Old hurt, and what it costs to keep it unnamed', 'What is something you have never fully allowed yourself to grieve?', 'Old hurt', '1 of 3', '21, 23', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (9, 'Adult', 1, 'See Clearly', true, 'The Wounds We Carry', 'The Kintsugi Audit', 'In the Japanese art of kintsugi, broken pottery is repaired with gold — the cracks made visible, made beautiful. The break is not hidden. It is honoured. The philosophy beneath it: what has broken is part of the story. The repair is part of the beauty. This is the practice of this session — not hiding the cracks, but beginning to look at them.', 'In the Japanese art of kintsugi, broken pottery is repaired with gold — the cracks made visible, made beautiful. The break is not hidden. It is honoured.', '', '', 'Old hurts are a heavy backpack you''ve worn so long you forgot it''s on — naming them in a safe room is setting it down for a minute. Today: name one thing you''ve been carrying, just to feel the weight lift.', 'Old hurts are a heavy backpack you''ve worn so long you forgot it''s on — naming them in a safe room is setting it down for a minute.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (10, 1, 'See Clearly', 'The Masks We Wear', 'See Clearly', 'The gap between the public self and the private one', 'Is there something you feel or want that you have never let yourself express?', 'Masks and being seen', '1 of 3', '22, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (10, 'Adult', 1, 'See Clearly', false, 'The Masks We Wear', 'Frontend and Backend', 'In theatre tradition the mask (persona) was originally a tool — it amplified voice and communicated character. But when the mask becomes fused to the face, the actor loses access to their own expression. The question is not whether you wear masks — everyone does. The question is: do you still know your own face?', 'In theatre tradition the mask (persona) was originally a tool — it amplified voice and communicated character.', '', '', 'Your profile is the filtered photo; the real you is the whole camera roll — and the right people want the camera roll. Today: show one true, unfiltered thing to someone safe.', 'Your profile is the filtered photo; the real you is the whole camera roll — and the right people want the camera roll.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (11, 1, 'See Clearly', 'Seeing Others Clearly', 'See Clearly', 'The unseen story behind someone else''s behaviour', 'Think of someone you find difficult. What might they be carrying?', 'Seeing others', '1 of 3', '44, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (11, 'Adult', 1, 'See Clearly', false, 'Seeing Others Clearly', 'Calibrating the Sensor', 'The Daoist tradition speaks of action without ego-driven interference. Applied to perception: to see clearly is to look without the constant overlaid commentary of our own needs, fears, and judgments. This is what contemplative traditions call direct perception — not easy, but profoundly possible with practice.', 'The Daoist tradition speaks of action without ego-driven interference.', '', '', 'Everyone''s driving with a dashcam you can''t see — the person who cut you off might be racing to a hospital. Today: give one person the benefit of their unseen story.', 'Everyone''s driving with a dashcam you can''t see — the person who cut you off might be racing to a hospital.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (12, 1, 'See Clearly', 'The Habit Loop — How We Got Here', 'See Clearly', 'Trigger, action, reward, and the automatic life', 'What do you do — reliably, almost without deciding — when you are uncomfortable?', 'Habits and structure', '1 of 4', '29, 33, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (12, 'Adult', 1, 'See Clearly', false, 'The Habit Loop — How We Got Here', 'Mapping the Loops', 'In Daoist thought the concept of wu wei is often misunderstood as passivity. It is actually the opposite: action so aligned with natural patterns that it requires no forcing. The master potter does not fight the clay — they understand its nature completely. Habit change works the same way: fighting habits through willpower fails. Working with their natural structure — understanding the loop — is how genuine change happens.', 'In Daoist thought the concept of wu wei is often misunderstood as passivity.', '', '', 'A habit is an autoplay playlist — one trigger and the next track just starts. Today: spot the trigger track for one habit and swap the next song on purpose.', 'A habit is an autoplay playlist — one trigger and the next track just starts.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (13, 1, 'See Clearly', 'Integration — What We Now See', 'See Clearly', 'Gathering the movement: signal, story, body, loop', 'What have you noticed about yourself in the last thirteen weeks that you hadn''t before?', 'Integration', '1 of 4', '26, 39, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (13, 'Adult', 1, 'See Clearly', false, 'Integration — What We Now See', 'The Audit Is Complete', 'In Daoist thought the completion of a cycle is not an ending but a turning — a return to the beginning with different eyes. What you''ve seen in yourself over the past 13 weeks contains both challenge and opportunity. The integration is choosing what to do with the opportunity.', 'In Daoist thought the completion of a cycle is not an ending but a turning — a return to the beginning with different eyes.', '', '', 'You''ve been handed a toolkit — a pause button, a feelings-iceberg, a mirror, a mute button for the critic. Today: pick the one tool you''ll actually keep in your pocket.', 'You''ve been handed a toolkit — a pause button, a feelings-iceberg, a mirror, a mute button for the critic.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (14, 2, 'Unlearn', 'The Permission You''re Still Waiting For', 'Unlearn', 'Waiting to be authorised by someone who is not coming', 'What are you waiting for permission to do?', 'Permission and values', '1 of 4', '15, 28, 43', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (14, 'Adult', 2, 'Unlearn', false, 'The Permission You''re Still Waiting For', 'You Are the Authority', 'There is a Daoist concept of zìrán — naturalness, or spontaneous self-expression. Not recklessness, but action that arises from your authentic nature rather than from waiting for external permission. The ancient teachers observed: the river does not wait for permission to flow. Neither does anything that is truly alive.', 'There is a Daoist concept of zìrán — naturalness, or spontaneous self-expression.', '', '', 'You keep refreshing an inbox for an approval email that''s never coming — because you''re the one who has to hit send. Today: give yourself the green light on one thing you''ve been waiting on.', 'You keep refreshing an inbox for an approval email that''s never coming — because you''re the one who has to hit send.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (15, 2, 'Unlearn', 'Letting Go of Who You Were Supposed to Be', 'Unlearn', 'The inherited script of should', 'Whose expectations are you still living inside?', 'Permission and values', '2 of 4', '14, 28, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (15, 'Adult', 2, 'Unlearn', false, 'Letting Go of Who You Were Supposed to Be', 'Default Settings and Custom Configuration', 'The Daoist concept of pu — the uncarved block — describes the state of original, unconditioned potential before social shaping has imposed a fixed form. You were once an uncarved block. A great deal has been carved since. The practice is not returning to the uncarved block — that''s impossible. The practice is distinguishing between carving you chose and carving that was done to you.', 'The Daoist concept of pu — the uncarved block — describes the state of original, unconditioned potential before social shaping has imposed a fixed form.', '', '', 'You''ve been reading lines off a teleprompter someone else wrote — but it isn''t your story. Today: put down one ''should'' and say the line that''s actually yours.', 'You''ve been reading lines off a teleprompter someone else wrote — but it isn''t your story. Today: put down one ''should'' and say the line that''s actually yours.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (16, 2, 'Unlearn', 'The Forgiveness Loop', 'Unlearn', 'Resentment, and who it actually costs', 'What are you still holding against someone, and what does holding it give you?', 'Forgiveness', '1 of 3', '17, 45', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (16, 'Adult', 2, 'Unlearn', true, 'The Forgiveness Loop', 'Completing the Process', 'Ancient wisdom traditions across cultures converge on a radical idea: forgiveness is not a gift given to the wrongdoer. It is freedom claimed by the one who was wronged. The Daoist tradition frames it as releasing attachment to the outcome — not approving of the harm, but releasing the grip of the harm on your present moment.', 'Ancient wisdom traditions across cultures converge on a radical idea: forgiveness is not a gift given to the wrongdoer.', '', '', 'Resentment is gripping a hot coal to throw at someone — you''re the one getting burned. Today: name one grudge and picture opening your hand and setting the coal down.', 'Resentment is gripping a hot coal to throw at someone — you''re the one getting burned.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (17, 2, 'Unlearn', 'Forgiving Yourself', 'Unlearn', 'Accountability without self-attack', 'Is there something you have not forgiven yourself for?', 'Forgiveness', '2 of 3', '16, 45', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (17, 'Adult', 2, 'Unlearn', true, 'Forgiving Yourself', 'Clearing the Cache', 'The concept of ren in Confucian and Daoist philosophy — often translated as benevolence or humaneness — was considered the highest virtue. Critically, it begins with the self: you cannot genuinely extend humaneness to others from a place of ongoing self-prosecution. The ancient teachers understood what modern psychology confirms: self-compassion is not selfishness. It is the foundation of genuine contribution.', 'The concept of ren in Confucian and Daoist philosophy — often translated as benevolence or humaneness — was considered the highest virtue.', '', '', 'You wouldn''t keep charging a friend for a debt they already paid — so stop billing yourself for the same mistake. Today: mark one thing ''paid — lesson kept'' and close the account.', 'You wouldn''t keep charging a friend for a debt they already paid — so stop billing yourself for the same mistake.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (18, 2, 'Unlearn', 'Rewiring the Critic — Building the Inner Coach', 'Unlearn', 'Turning the harsh voice into an honest one', 'What would a fair version of that voice have said instead?', 'The inner voice', '2 of 3', '7, 32', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (18, 'Adult', 2, 'Unlearn', false, 'Rewiring the Critic — Building the Inner Coach', 'Building the Better Architecture', 'The Daoist concept of the master teacher is instructive here: a true master does not diminish the student. They challenge them toward their actual capacity. The inner critic mistakes diminishment for challenge. The inner coach knows the difference. Building the inner coach is the practice of becoming your own true master.', 'The Daoist concept of the master teacher is instructive here: a true master does not diminish the student. They challenge them toward their actual capacity.', '', '', 'Swap the heckler in your head for a good coach — same honesty, opposite tone. Today: rewrite one harsh line the way a great coach would say it.', 'Swap the heckler in your head for a good coach — same honesty, opposite tone. Today: rewrite one harsh line the way a great coach would say it.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (19, 2, 'Unlearn', 'Breaking the People-Pleasing Pattern', 'Unlearn', 'Kindness from fear against kindness from choice', 'When did you last say yes when you meant no?', 'Choice and response', '2 of 3', '3, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (19, 'Adult', 2, 'Unlearn', false, 'Breaking the People-Pleasing Pattern', 'Reorienting the Function', 'The Daoist concept of ziran — natural, spontaneous action arising from one''s true nature — stands in direct contrast to the people-pleasing pattern. The Daoist teachers observed: when a tree grows toward its natural form, it is beautiful. When it is trained to grow in someone else''s preferred direction, it survives — but at a cost. The branches that grow against the grain are where the beauty actually lives.', 'The Daoist concept of ziran — natural, spontaneous action arising from one''s true nature — stands in direct contrast to the people-pleasing pattern.', '', '', 'Saying yes to everything is never closing any apps — your battery hits 1% by noon; a boundary is low-power mode on purpose. Today: turn one fear-''yes'' into an honest ''no''.', 'Saying yes to everything is never closing any apps — your battery hits 1% by noon; a boundary is low-power mode on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (20, 2, 'Unlearn', 'Unlearning Scarcity — There Is Enough', 'Unlearn', 'The belief that there is not enough to go round', 'What do you hold back on, in case there isn''t enough?', 'Enough', '2 of 3', '6, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (20, 'Adult', 2, 'Unlearn', false, 'Unlearning Scarcity — There Is Enough', 'Uninstalling the Scarcity Operating System', 'The Daoist concept of ziran — naturalness — includes the observation that nature itself does not operate from scarcity. A tree does not ration its leaves. A river does not calculate whether there is enough water to keep flowing. The scarcity mindset is imposed, not inherent. The ancient practice was to observe nature''s abundance and learn to trust it.', 'The Daoist concept of ziran — naturalness — includes the observation that nature itself does not operate from scarcity. A tree does not ration its leaves.', '', '', 'Kindness isn''t a biscuit tin that empties — it''s a candle that lights other candles and loses nothing. Today: give something away as if it multiplies, because it does.', 'Kindness isn''t a biscuit tin that empties — it''s a candle that lights other candles and loses nothing.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (21, 2, 'Unlearn', 'The Relationships That Shaped You', 'Unlearn', 'What we absorbed from the people who raised and marked us', 'What did you learn about love from the people who raised you?', 'Old hurt', '2 of 3', '9, 23', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (21, 'Adult', 2, 'Unlearn', true, 'The Relationships That Shaped You', 'Structural Assessment', 'The concept of relational wisdom in ancient traditions: Confucian thought emphasised the five fundamental relationships as the basis of a well-lived life — but always with the caveat that those relationships had to be honestly examined and consciously enacted, not merely inherited and repeated. Daoist thought added: the quality of any relationship depends on the quality of the person''s relationship with themselves first.', 'The concept of relational wisdom in ancient traditions: Confucian thought emphasised the five fundamental relationships as the basis of a well-lived life — but always with the caveat…', '', '', 'You inherited relationship ''settings'' the way a phone ships with defaults — some are great, some need updating. Today: spot one default about love you want to change.', 'You inherited relationship ''settings'' the way a phone ships with defaults — some are great, some need updating. Today: spot one default about love you want to change.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (22, 2, 'Unlearn', 'Setting Down the Armour', 'Unlearn', 'The defences that now keep connection out', 'What are you protecting, and who is it keeping out?', 'Masks and being seen', '2 of 3', '10, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (22, 'Adult', 2, 'Unlearn', false, 'Setting Down the Armour', 'Updating the Security System', 'The Daoist concept of rou — softness, yielding, flexibility — is consistently described as the ultimate form of strength. ''The softest things in the world overcome the hardest things in the world.'' The armoured surface resists but eventually cracks. The yielding surface absorbs and sustains. Setting down the armour is not weakness — it is the deeper form of strength.', 'The Daoist concept of rou — softness, yielding, flexibility — is consistently described as the ultimate form of strength.', '', '', 'The armour that got you through school now sets off the metal detector at the hug. Today: lower one piece of armour — sarcasm, busyness, control — with one safe person.', 'The armour that got you through school now sets off the metal detector at the hug.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (23, 2, 'Unlearn', 'Grief and Growth — What Endings Make Possible', 'Unlearn', 'Loss, and the ground it clears', 'What ended that you have not properly mourned?', 'Old hurt', '3 of 3', '9, 21', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (23, 'Adult', 2, 'Unlearn', true, 'Grief and Growth — What Endings Make Possible', 'Completing the Close', 'The concept of wu wei — not forcing, flowing with what is — applies directly to grief. Ancient wisdom traditions did not seek to eliminate grief. They created containers for it: mourning rituals, community witness, periods of designated sorrow. The container was not there to extend the grief indefinitely — but to ensure it was fully moved through, not skipped over.', 'The concept of wu wei — not forcing, flowing with what is — applies directly to grief. Ancient wisdom traditions did not seek to eliminate grief.', '', '', 'Winter looks like the tree died, but it''s just clearing the branches for spring. Today: name what an ending has quietly made room for.', 'Winter looks like the tree died, but it''s just clearing the branches for spring. Today: name what an ending has quietly made room for.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (24, 2, 'Unlearn', 'Rewiring Fear — From Threat to Signal', 'Unlearn', 'Reading the body''s alarm as information', 'What are you afraid of that has never actually happened?', 'The body', '2 of 3', '4, 30', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (24, 'Adult', 2, 'Unlearn', true, 'Rewiring Fear — From Threat to Signal', 'Calibrating the Threat Sensor', 'The ancient practices of sitting with discomfort — meditation, fasting, cold exposure, ritual endurance — were never about punishment. They were about distinguishing real threat from discomfort, and building the nervous system''s tolerance for the unknown. The Daoist master sat with uncertainty as a practice — not because certainty was unavailable, but because the capacity to act in uncertainty was worth cultivating.', 'The ancient practices of sitting with discomfort — meditation, fasting, cold exposure, ritual endurance — were never about punishment.', '', '', 'Most alarms in your head are burnt toast, not a house fire — the smoke detector just can''t tell the difference. Today: label one fear ''burnt toast'' and open a window instead of running.', 'Most alarms in your head are burnt toast, not a house fire — the smoke detector just can''t tell the difference.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (25, 2, 'Unlearn', 'The Stories That No Longer Serve', 'Unlearn', 'Honouring an old narrative, then rewriting it', 'What story about yourself protected you once and now costs you?', 'Stories and identity', '3 of 5', '2, 5, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (25, 'Adult', 2, 'Unlearn', false, 'The Stories That No Longer Serve', 'Writing the Upgrade', 'The Daoist concept of transformation — hua — describes the natural process of change as intrinsic to all living systems. A thing that cannot transform dies. The capacity to release old stories and author new ones is not just a psychological practice — it is the expression of a living, growing system doing exactly what it was designed to do.', 'The Daoist concept of transformation — hua — describes the natural process of change as intrinsic to all living systems. A thing that cannot transform dies.', '', '', 'An old story is a saved route on your maps app that no longer goes where you live. Today: delete one outdated ''I always…'' and set a new destination.', 'An old story is a saved route on your maps app that no longer goes where you live.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (26, 2, 'Unlearn', 'Integration — What We Have Released', 'Unlearn', 'Gathering the movement: permission, resentment, armour, story', 'What have you set down, and what is still in your hands?', 'Integration', '2 of 4', '13, 39, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (26, 'Adult', 2, 'Unlearn', false, 'Integration — What We Have Released', 'Cleared Ground', 'The Daoist concept of returning to the source — gui gen — describes the deepening of roots before new growth. You cannot build upward without going deeper first. Phase 2 has been the root work. Phase 3 is the growth that roots make possible.', 'The Daoist concept of returning to the source — gui gen — describes the deepening of roots before new growth. You cannot build upward without going deeper first.', '', '', 'You''ve cleared a pile of old apps clogging the phone — permission-seeking, resentment, armour. Today: notice how much lighter and faster you run without them.', 'You''ve cleared a pile of old apps clogging the phone — permission-seeking, resentment, armour. Today: notice how much lighter and faster you run without them.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (27, 3, 'Rebuild', 'Who Are You Now? — Rebuilding Identity', 'Rebuild', 'Identity as something chosen rather than inherited', 'If nobody had told you who you were, who would you be?', 'Stories and identity', '4 of 5', '2, 5, 25, 49', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (27, 'Adult', 3, 'Rebuild', false, 'Who Are You Now? — Rebuilding Identity', 'Configuration Begins', 'The Daoist concept of ziran — naturalness, authentic self-expression — describes an identity that arises from within rather than being imposed from without. This is not the identity you were given. It is the identity you discover through honest living, through released patterns, through the choices you make when the noise has quieted enough to hear something true.', 'The Daoist concept of ziran — naturalness, authentic self-expression — describes an identity that arises from within rather than being imposed from without.', '', '', 'Instead of the labels stuck on you like airport baggage tags, you get to pack your own bag. Today: choose the three qualities you''re building yourself from.', 'Instead of the labels stuck on you like airport baggage tags, you get to pack your own bag. Today: choose the three qualities you''re building yourself from.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (28, 3, 'Rebuild', 'What Do You Actually Value?', 'Rebuild', 'The compass underneath the goals', 'What would you not trade, whatever you were offered for it?', 'Permission and values', '3 of 4', '14, 15, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (28, 'Adult', 3, 'Rebuild', false, 'What Do You Actually Value?', 'Setting the Priority Hierarchy', 'The Confucian tradition placed values — ren (benevolence), yi (righteousness), li (ritual propriety), zhi (wisdom), xin (integrity) — at the centre of the well-lived life. Not as abstract ideals but as living practices, tested and refined daily. The Daoist tradition added: values that are genuine arise naturally from the person''s authentic nature. Forced values are performance. Chosen values are life.', 'The Confucian tradition placed values — ren (benevolence), yi (righteousness), li (ritual propriety), zhi (wisdom), xin (integrity) — at the centre of the well-lived life.', '', '', 'Values are your GPS ''home'' setting — every turn is easier once it''s locked in. Today: name your true-north value and check one recent decision against it.', 'Values are your GPS ''home'' setting — every turn is easier once it''s locked in. Today: name your true-north value and check one recent decision against it.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (29, 3, 'Rebuild', 'The Habits That Build You', 'Rebuild', 'Small daily practice as the architecture of a self', 'What do you do every day that is quietly making you someone?', 'Habits and structure', '2 of 4', '12, 33, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (29, 'Adult', 3, 'Rebuild', false, 'The Habits That Build You', 'Installing the New Architecture', 'The Daoist concept of small, consistent alignment — rather than dramatic, exhausting effort — is the most durable form of change. ''The journey of ten thousand miles begins with one step.'' Not the right conditions, not the perfect system, not enough confidence — just the one step. Then the next. Then the pattern, forming like a path.', 'The Daoist concept of small, consistent alignment — rather than dramatic, exhausting effort — is the most durable form of change.', '', '', 'You don''t get fit from one epic gym session — you get fit from showing up small and often; identity works the same. Today: pick the 1% habit you''ll repeat like brushing your teeth.', 'You don''t get fit from one epic gym session — you get fit from showing up small and often; identity works the same.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (30, 3, 'Rebuild', 'Your Body as Foundation', 'Rebuild', 'Sleep, movement, food, calm — the base everything sits on', 'What does your body need that you have been overriding?', 'The body', '3 of 3', '4, 24', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (30, 'Adult', 3, 'Rebuild', false, 'Your Body as Foundation', 'The Hardware Layer', 'The ancient mind-body traditions were never body practices with a spiritual dimension, or spiritual practices with a physical component. They were one thing: the understanding that consciousness and physicality are not separate. Qigong, yoga, tai chi, meditation — all are practices of the integrated whole. The rebuild honours the whole.', 'The ancient mind-body traditions were never body practices with a spiritual dimension, or spiritual practices with a physical component.', '', '', 'Your body is the phone the whole day runs on, and sleep, movement, food and calm are the four charging cables. Today: plug in the one that''s most drained.', 'Your body is the phone the whole day runs on, and sleep, movement, food and calm are the four charging cables.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (31, 3, 'Rebuild', 'The People You Choose', 'Rebuild', 'The relationships that shape the life', 'Who do you become around the people you spend most time with?', 'Belonging', '1 of 3', '38, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (31, 'Adult', 3, 'Rebuild', false, 'The People You Choose', 'Designing the Social Environment', 'The concept of sangha — the community of like-minded practitioners — is one of the three jewels in Buddhist tradition (alongside the teaching and the practice itself). The Daoist tradition emphasises learning from those whose nature is aligned with yours. Neither tradition considered the social environment incidental to growth. Both considered it foundational.', 'The concept of sangha — the community of like-minded practitioners — is one of the three jewels in Buddhist tradition (alongside the teaching and the practice itself).', '', '', 'You become the average of your five most-opened contacts. Today: pick one relationship to open more, and one notification to turn down.', 'You become the average of your five most-opened contacts. Today: pick one relationship to open more, and one notification to turn down.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (32, 3, 'Rebuild', 'How You Speak to Yourself', 'Rebuild', 'The tone of the inner voice under pressure', 'What would you say to someone you loved who was where you are?', 'The inner voice', '3 of 3', '7, 18', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (32, 'Adult', 3, 'Rebuild', false, 'How You Speak to Yourself', 'The Daily Soundtrack', 'The practice of mantra in many ancient traditions was not about magical words — it was about deliberately shaping the quality of the mind''s habitual content. What you repeat internally, you eventually become. The Daoist concept of yi — intention — includes the quality of one''s inner speech as a fundamental practice.', 'The practice of mantra in many ancient traditions was not about magical words — it was about deliberately shaping the quality of the mind''s habitual content.', '', '', 'Talk to yourself like you''d text a friend having a hard day — not like an anonymous troll in the comments. Today: keep one kind phrase in your pocket for the next hard moment.', 'Talk to yourself like you''d text a friend having a hard day — not like an anonymous troll in the comments.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (33, 3, 'Rebuild', 'Creating Structure That Serves You', 'Rebuild', 'Rhythm and routine as trellis rather than cage', 'What in your week is structure, and what is just habit?', 'Habits and structure', '3 of 4', '12, 29, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (33, 'Adult', 3, 'Rebuild', false, 'Creating Structure That Serves You', 'Designing the Container', 'The ancient traditions all had daily structures — prayer times, practice periods, meal rhythms, rest cycles. Not as restriction, but as container. The container doesn''t limit the water — it gives the water a shape. Your daily structure is the container your life pours into. Design it deliberately.', 'The ancient traditions all had daily structures — prayer times, practice periods, meal rhythms, rest cycles. Not as restriction, but as container.', '', '', 'Routine isn''t a cage — it''s the trellis a plant climbs to reach the light. Today: add one small anchor (same wake time, one blocked hour) and let freedom grow on it.', 'Routine isn''t a cage — it''s the trellis a plant climbs to reach the light.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (34, 3, 'Rebuild', 'Rest as a Practice, Not a Reward', 'Rebuild', 'Restoration that isn''t earned', 'When did you last rest without guilt?', 'Signal and attention', '2 of 4', '1, 50, 51', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (34, 'Adult', 3, 'Rebuild', false, 'Rest as a Practice, Not a Reward', 'Scheduled Maintenance', 'The Sabbath principle — found in Jewish, Christian, Islamic, and secular traditions — is one of the most ancient and cross-culturally consistent human insights about sustainable living. One day in seven deliberately different from the others. Not as religious obligation, but as evidence of what humans have always known about the rhythm that sustains. Rest is not interruption. Rest is the breath between notes that makes music possible.', 'The Sabbath principle — found in Jewish, Christian, Islamic, and secular traditions — is one of the most ancient and cross-culturally consistent human insights about sustainable living.', '', '', 'You plug your phone in before it dies, not after — do the same for yourself. Today: schedule one real rest block before you''re down to 1%.', 'You plug your phone in before it dies, not after — do the same for yourself. Today: schedule one real rest block before you''re down to 1%.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (35, 3, 'Rebuild', 'Creativity and Expression', 'Rebuild', 'Making things for their own sake', 'What did you love making before anyone told you if you were good at it?', 'Creativity and expression', '1 of 3', '41, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (35, 'Adult', 3, 'Rebuild', false, 'Creativity and Expression', 'Restoring the Output Channel', 'The Daoist concept of wu — nothingness, the space from which creation emerges — describes the ground of all creative expression. The empty bowl can be filled. The empty page can be written on. Creativity does not begin with having something to say. It begins with making space for what is already true to find its form.', 'The Daoist concept of wu — nothingness, the space from which creation emerges — describes the ground of all creative expression. The empty bowl can be filled.', '', '', 'Making something is like cooking for yourself — it doesn''t need a Michelin star to feed you. Today: make one small thing no one will grade.', 'Making something is like cooking for yourself — it doesn''t need a Michelin star to feed you. Today: make one small thing no one will grade.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (36, 3, 'Rebuild', 'Purpose — What You''re Here For', 'Rebuild', 'Where what you have meets what is needed', 'What are you doing when you lose track of time?', 'Purpose', '1 of 3', '40, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (36, 'Adult', 3, 'Rebuild', false, 'Purpose — What You''re Here For', 'Orienting Toward What Is Genuinely Yours', 'The Japanese concept of ikigai — often translated as ''reason for being'' — sits at the intersection of what you love, what you are good at, what the world needs, and what you can be compensated for. It is not a single answer but a living orientation. The Daoist equivalent: the practice that feels most aligned with your nature. When you find what is genuinely yours to do, the work itself becomes the practice.', 'The Japanese concept of ikigai — often translated as ''reason for being'' — sits at the intersection of what you love, what you are good at, what the…', '', '', 'Purpose is where your skills and the world''s needs overlap — the sweet spot of the Venn diagram. Today: name one small place that overlap already exists.', 'Purpose is where your skills and the world''s needs overlap — the sweet spot of the Venn diagram. Today: name one small place that overlap already exists.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (37, 3, 'Rebuild', 'Money, Abundance and Your Relationship With Resources', 'Rebuild', 'Inherited scripts about resources, need and enough', 'What did you learn about money before you were old enough to question it?', 'Resources', '2 of 3', '20, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (37, 'Adult', 3, 'Rebuild', false, 'Money, Abundance and Your Relationship With Resources', 'Rebuilding the Resource Relationship', 'The Daoist concept of flow — zi ran — applies as powerfully to material resources as to any other domain. Resources that flow freely, in alignment with values, circulate and generate. Resources that are gripped too tightly or expelled too anxiously stagnate or deplete. The practice is right relationship — neither grasping nor abandoning.', 'The Daoist concept of flow — zi ran — applies as powerfully to material resources as to any other domain.', '', '', 'Your money ''scripts'' are inherited apps running in the background of every purchase. Today: sort one thing into need / want / could-share and notice which script ran.', 'Your money ''scripts'' are inherited apps running in the background of every purchase. Today: sort one thing into need / want / could-share and notice which script ran.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (38, 3, 'Rebuild', 'The Community You Build', 'Rebuild', 'Contribution, and being part of something', 'What do you bring that a room is worse off without?', 'Belonging', '2 of 3', '31, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (38, 'Adult', 3, 'Rebuild', false, 'The Community You Build', 'Building the Ecology of Growth', 'The concept of sangha — spiritual community — is one of the three jewels of Buddhist practice. The Confucian tradition places right relationship with community at the centre of the well-lived life. Mindcast LIVE itself is an expression of this ancient insight: personal growth is most durable, most honest, and most alive when it happens in the presence of others doing the same work.', 'The concept of sangha — spiritual community — is one of the three jewels of Buddhist practice.', '', '', 'A community is a beehive — it works because everyone brings something back. Today: name the one thing you''ll bring to a room you want to belong to.', 'A community is a beehive — it works because everyone brings something back. Today: name the one thing you''ll bring to a room you want to belong to.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (39, 3, 'Rebuild', 'Integration — Who You Are Becoming', 'Rebuild', 'Gathering the movement: values, habits, body, people', 'What is different about how you live now?', 'Integration', '3 of 4', '13, 26, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (39, 'Adult', 3, 'Rebuild', false, 'Integration — Who You Are Becoming', 'The Foundation Is Laid', 'In Daoist tradition, the master is not the one who has arrived — it is the one who has committed to the practice. The practice is not preparation for living. The practice IS living. Phase 3 has been the practice. Phase 4 is living from it, fully, in the world.', 'In Daoist tradition, the master is not the one who has arrived — it is the one who has committed to the practice.', '', '', 'The building site is now a home you can live in — identity, values, habits, people. Today: name who you''ve become, and step through the door into living it.', 'The building site is now a home you can live in — identity, values, habits, people.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (40, 4, 'Live It', 'From Self-Development to Service', 'Live It', 'What the inner work is ultimately for', 'Who is better off because of the work you''ve done this year?', 'Purpose', '2 of 3', '36, 49', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (40, 'Adult', 4, 'Live It', false, 'From Self-Development to Service', 'The Turn Outward', 'The Daoist and Confucian traditions converge on this: genuine inner cultivation naturally expresses itself outward. The sage does not hoard wisdom — they embody it in relationship, in action, in the quality of their presence. Service is not the sacrifice of self. It is the fullest expression of it.', 'The Daoist and Confucian traditions converge on this: genuine inner cultivation naturally expresses itself outward.', '', '', 'You don''t hoard the wifi password once you''re connected — you share it; inner work is the same. Today: give one thing you''ve healed enough to offer someone else.', 'You don''t hoard the wifi password once you''re connected — you share it; inner work is the same.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (41, 4, 'Live It', 'Teaching What You''ve Learned', 'Live It', 'Understanding something twice by passing it on', 'What do you know now that you wish someone had told you?', 'Creativity and expression', '2 of 3', '35, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (41, 'Adult', 4, 'Live It', false, 'Teaching What You''ve Learned', 'The Test of Understanding', 'In the Confucian tradition, the transmission of wisdom from teacher to student is one of the most sacred relationships. Not because the teacher is infallible — but because the act of conscious transmission deepens both parties. The Daoist teacher teaches not by telling but by embodying: the most powerful transmission is a life lived with integrity.', 'In the Confucian tradition, the transmission of wisdom from teacher to student is one of the most sacred relationships.', '', '', 'Explaining something to a ten-year-old is how you find out you actually understand it. Today: put one lesson into one plain sentence and pass it on.', 'Explaining something to a ten-year-old is how you find out you actually understand it. Today: put one lesson into one plain sentence and pass it on.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (42, 4, 'Live It', 'The Courage to Be Seen', 'Live It', 'Exposure, and what lies past the fear of judgement', 'What is true about you that you have never let anyone see?', 'Masks and being seen', '3 of 3', '10, 22', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (42, 'Adult', 4, 'Live It', true, 'The Courage to Be Seen', 'Going Live', 'The Daoist concept of de — virtue, power, genuine nature — is not a private quality. It is expressed through presence, through action, through the quality of how you show up in relationship. You cannot embody virtue in isolation. It must be lived in encounter. The courage to be seen is not optional. It is the practice itself.', 'The Daoist concept of de — virtue, power, genuine nature — is not a private quality.', '', '', 'Turning your camera on in the meeting is scary for two seconds and connecting for the rest. Today: show up ''camera-on'' in one place you usually hide.', 'Turning your camera on in the meeting is scary for two seconds and connecting for the rest. Today: show up ''camera-on'' in one place you usually hide.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (43, 4, 'Live It', 'Living Your Values Under Pressure', 'Live It', 'What holds when it costs something', 'When did you last act against your own values, and what was the pressure?', 'Emotions as data', '3 of 3', '8, 24', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (43, 'Adult', 4, 'Live It', false, 'Living Your Values Under Pressure', 'Values Under Load', 'The Daoist and Confucian traditions both speak of this: virtue is not a fair-weather quality. The character of a person is revealed in difficulty. The practice is not performing integrity when it is easy — it is returning to it when it is costly, and doing so consistently enough that it becomes genuinely who you are rather than who you are trying to be.', 'The Daoist and Confucian traditions both speak of this: virtue is not a fair-weather quality. The character of a person is revealed in difficulty.', '', '', 'Your values are only real in the storm, not the sunshine — like a compass that has to work when the sky goes dark. Today: name one value you''ll hold even when it costs you.', 'Your values are only real in the storm, not the sunshine — like a compass that has to work when the sky goes dark.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (44, 4, 'Live It', 'Conflict as a Growth Practice', 'Live It', 'Staying in the difficulty rather than leaving it', 'What conflict have you been avoiding, and what are you protecting?', 'Seeing others', '2 of 3', '11, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (44, 'Adult', 4, 'Live It', false, 'Conflict as a Growth Practice', 'The Interface Layer', 'The Daoist tradition speaks of yin and yang — not as opposites that cancel each other out, but as complements that, in their tension, produce movement and life. Conflict, handled with awareness and integrity, is not a failure of harmony. It is harmony''s more demanding form. The practice is bringing the same quality of awareness to conflict that we bring to any other aspect of inner life.', 'The Daoist tradition speaks of yin and yang — not as opposites that cancel each other out, but as complements that, in their tension, produce movement and life.', '', '', '''You always…'' starts a fight; ''I feel… I need…'' starts a conversation. Today: rewrite one hard message in the second language.', '''You always…'' starts a fight; ''I feel… I need…'' starts a conversation. Today: rewrite one hard message in the second language.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (45, 4, 'Live It', 'Generosity as a Way of Being', 'Live It', 'Giving that grows the giver', 'What do you give that costs you nothing and matters to someone?', 'Forgiveness', '3 of 3', '16, 17', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (45, 'Adult', 4, 'Live It', false, 'Generosity as a Way of Being', 'Hands Open', 'The Daoist concept of te — virtue, generosity of spirit — is not about grand gestures. It is about the quality of ordinary presence: whether you arrive with hands open or closed, whether you offer freely or calculate, whether you treat every encounter as an opportunity for mutual enrichment. Generosity at this level is not what you do on occasion. It is who you are.', 'The Daoist concept of te — virtue, generosity of spirit — is not about grand gestures.', '', '', 'Some gifts — encouragement, time, attention — cost nothing and still glow in your own hands after you give them. Today: give one non-money gift by Sunday.', 'Some gifts — encouragement, time, attention — cost nothing and still glow in your own hands after you give them. Today: give one non-money gift by Sunday.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (46, 4, 'Live It', 'Enough — Living From Sufficiency', 'Live It', 'Noticing what is already good', 'What is already enough that you keep treating as not yet?', 'Enough', '3 of 3', '6, 20', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (46, 'Adult', 4, 'Live It', false, 'Enough — Living From Sufficiency', 'The Stable Baseline', 'The Daoist principle of zhi zu — knowing when enough is enough — is not about limitation. It is about wisdom: the recognition that the relentless accumulation beyond genuine need produces diminishing returns and increasing anxiety. The person who knows enough is wealthy. The person who never knows enough is perpetually poor, regardless of what they have.', 'The Daoist principle of zhi zu — knowing when enough is enough — is not about limitation.', '', '', 'The ''add to cart'' feeling is a treadmill — one more thing never becomes enough. Today: name three things you already have that are genuinely enough.', 'The ''add to cart'' feeling is a treadmill — one more thing never becomes enough. Today: name three things you already have that are genuinely enough.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (47, 4, 'Live It', 'The Long Game — Patience and Persistence', 'Live It', 'Growth that is invisible before it is visible', 'What are you working on that has not shown results yet?', 'Habits and structure', '4 of 4', '12, 29, 33', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (47, 'Adult', 4, 'Live It', false, 'The Long Game — Patience and Persistence', 'Trusting the Process', 'The Daoist principle of wu wei includes patience — not passive waiting, but the trust that processes allowed to unfold in their natural time produce more durable results than those forced prematurely. The seed does not become the tree on the gardener''s schedule. The practice is consistent, patient tending — without demanding the harvest before the season.', 'The Daoist principle of wu wei includes patience — not passive waiting, but the trust that processes allowed to unfold in their natural time produce more durable results…', '', '', 'A seed spends weeks looking like nothing while it grows roots — don''t dig it up to check. Today: recommit to one slow, unglamorous thing that''s still growing underground.', 'A seed spends weeks looking like nothing while it grows roots — don''t dig it up to check.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (48, 4, 'Live It', 'Leaving People Better Than You Found Them', 'Live It', 'Small moments that ripple further than we see', 'Who left you better than they found you, and how?', 'Seeing others', '3 of 3', '11, 44', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (48, 'Adult', 4, 'Live It', false, 'Leaving People Better Than You Found Them', 'Positive Externalities', 'The Confucian concept of ren — benevolence, humaneness — in its most practical form is exactly this: every encounter is an opportunity to extend genuine humanity toward another person. Not grand acts. Daily ones. A word of honest appreciation, a quality of genuine attention, a piece of honestly given wisdom — these are ren in practice.', 'The Confucian concept of ren — benevolence, humaneness — in its most practical form is exactly this: every encounter is an opportunity to extend genuine humanity toward another…', '', '', 'You leave a ''tip'' in every interaction — a little brighter or a little dimmer. Today: leave one person brighter, on purpose.', 'You leave a ''tip'' in every interaction — a little brighter or a little dimmer. Today: leave one person brighter, on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (49, 4, 'Live It', 'Your Legacy — What You''re Building Beyond Yourself', 'Live It', 'The part of you that outlasts you', 'What do you want to be true because you were here?', 'Stories and identity', '5 of 5', '2, 5, 25, 27', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (49, 'Adult', 4, 'Live It', false, 'Your Legacy — What You''re Building Beyond Yourself', 'What Are You Actually Building?', 'The Confucian concept of moral cultivation was always understood as inherently intergenerational. The sages cultivated themselves not only for their own flourishing but for the quality of presence they would offer to those around them and those who would come after. To live well is to leave something worth inheriting.', 'The Confucian concept of moral cultivation was always understood as inherently intergenerational.', '', '', 'Drop a stone in a pond and the ripples reach edges you''ll never see. Today: name one mark you want rippling out from how you live.', 'Drop a stone in a pond and the ripples reach edges you''ll never see. Today: name one mark you want rippling out from how you live.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (50, 4, 'Live It', 'Gratitude as a Practice, Not a Feeling', 'Live It', 'Specific noticing, trained', 'What is good right now that you had stopped noticing?', 'Signal and attention', '3 of 4', '1, 34, 51', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (50, 'Adult', 4, 'Live It', false, 'Gratitude as a Practice, Not a Feeling', 'Deliberate Attention', 'The ancient practices of gratitude — found in virtually every wisdom tradition — were never about performing happiness or denying difficulty. They were about deliberately redirecting attention to what is genuinely present and valuable, as a counter to the mind''s natural negative-bias drift. The Daoist sage lives in appreciation of what is — not because everything is pleasant, but because appreciation is a more alive relationship with reality than complaint.', 'The ancient practices of gratitude — found in virtually every wisdom tradition — were never about performing happiness or denying difficulty.', '', '', 'Gratitude is a camera — the more you practise pointing it, the more good it finds in frame. Today: capture three specific good moments in words, not generic ones.', 'Gratitude is a camera — the more you practise pointing it, the more good it finds in frame.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (51, 4, 'Live It', 'The Ongoing Practice — There Is No Arrival', 'Live It', 'Growth without a finish line', 'What will you keep doing when this year ends?', 'Signal and attention', '4 of 4', '1, 34, 50', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (51, 'Adult', 4, 'Live It', false, 'The Ongoing Practice — There Is No Arrival', 'The Practice That Keeps Practising', 'The Daoist master is not the one who has finished the practice. The master is the one who has understood that the practice never finishes — and who has found genuine delight in that fact. The absence of arrival is not failure. It is the nature of a living practice. It is the thing that makes it alive.', 'The Daoist master is not the one who has finished the practice.', '', '', 'There''s no ''finish line'' notification for growth — the walk is the point. Today: name the one practice you''ll keep for life, arrival or not.', 'There''s no ''finish line'' notification for growth — the walk is the point. Today: name the one practice you''ll keep for life, arrival or not.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (52, 4, 'Live It', 'Integration — A Year of Becoming', 'Live It', 'Gathering the whole arc', 'Who were you a year ago, and what would you tell them?', 'Integration', '4 of 4', '13, 26, 39', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (52, 'Adult', 4, 'Live It', false, 'Integration — A Year of Becoming', 'The Ceremony of Acknowledgment', 'In the oldest traditions of inner work, the final ceremony was not about the teacher pronouncing the student complete. It was about the student pronouncing themselves in ongoing practice — publicly, in community, with full awareness of what had been done and what remained to do. This is that ceremony.', 'In the oldest traditions of inner work, the final ceremony was not about the teacher pronouncing the student complete.', '', '', 'You''re not closing a book, you''re turning to a blank page with a full backpack and a compass. Today: write the first line of next year''s chapter.', 'You''re not closing a book, you''re turning to a blank page with a full backpack and a compass. Today: write the first line of next year''s chapter.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (1, 1, 'See Clearly', 'The Signal and the Noise', 'See Clearly', 'The noise in your head, and the quieter thing underneath it', 'What are you carrying that nobody around you knows about?', 'Signal and attention', '1 of 4', '34, 50, 51', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (1, 'Teen', 1, 'See Clearly', false, 'The Signal and the Noise', 'Who''s Actually Talking?', 'Old navigators used stars when everything else was uncertain — not because the stars told them what to do, but because they were reliable. You have something like that too. Most people just never learn to look for it.', 'Old navigators used stars when everything else was uncertain — not because the stars told them what to do, but because they were reliable.', '', '', 'Your mind is a phone with 47 tabs open and notifications firing — the signal is the one tab you opened on purpose. Today: close the tabs (one breath, one thing) and hear the quiet channel underneath the noise.', 'Your mind is a phone with 47 tabs open and notifications firing — the signal is the one tab you opened on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (2, 1, 'See Clearly', 'The Stories We Carry', 'See Clearly', 'The things you''ve been told about yourself so often you stopped checking', 'What''s something you''ve always been told you are — and is it actually true?', 'Stories and identity', '1 of 5', '5, 25, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (2, 'Teen', 1, 'See Clearly', false, 'The Stories We Carry', 'The Playlist You Didn''t Choose', 'There''s an old idea: ''The fish doesn''t know it''s wet.'' When you''ve been swimming in a story your whole life, it feels like reality. The practice is climbing out of the water long enough to see it for what it is.', 'There''s an old idea: ''The fish doesn''t know it''s wet.'' When you''ve been swimming in a story your whole life, it feels like reality.', '', '', 'The stories you tell about yourself run like an app in the background, quietly draining the battery. Today: catch one ''I''m the kind of person who…'' and ask — did I write this, or did it just install itself?', 'The stories you tell about yourself run like an app in the background, quietly draining the battery.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (3, 1, 'See Clearly', 'The Pattern Interrupt', 'See Clearly', 'The tiny gap between something happening and you reacting', 'When did you last snap at someone and wish you hadn''t?', 'Choice and response', '1 of 3', '19, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (3, 'Teen', 1, 'See Clearly', false, 'The Pattern Interrupt', 'The Chat You''re Not Reading', 'There''s an idea: the obstacle is the path — the thing that trips you up shows you exactly where you need to grow. Your patterns aren''t your enemies. They''re messengers. Loud, sometimes destructive messengers. But still.', 'There''s an idea: the obstacle is the path — the thing that trips you up shows you exactly where you need to grow. Your patterns aren''t your enemies.', '', '', 'Between the notification buzzing and your hand grabbing the phone there''s a half-second gap — that gap is a superpower. Today: find the buzz-to-grab gap in one habit and slot a single breath into it.', 'Between the notification buzzing and your hand grabbing the phone there''s a half-second gap — that gap is a superpower.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (4, 1, 'See Clearly', 'What Your Body Is Telling You', 'See Clearly', 'What your body notices before your brain catches up', 'Where do you feel it in your body when you''re nervous?', 'The body', '1 of 3', '24, 30', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (4, 'Teen', 1, 'See Clearly', false, 'What Your Body Is Telling You', 'Reading the Data Your Body Collects', 'Ancient practices like yoga, martial arts, and dance were never just physical. They were ways of developing body intelligence — the ability to feel what the body knows before the mind catches up. Modern science confirms what these traditions knew: the gut has as many neurons as a cat''s brain. Your body is thinking, even when you''re not.', 'Ancient practices like yoga, martial arts, and dance were never just physical.', '', '', 'Your body is the check-engine light your dashboard mind keeps ignoring — tight shoulders and a clenched jaw are data, not noise. Today: do a ten-second body scan before you fire back the stressful message.', 'Your body is the check-engine light your dashboard mind keeps ignoring — tight shoulders and a clenched jaw are data, not noise.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (5, 1, 'See Clearly', 'The Mirror — How We See Ourselves', 'See Clearly', 'Seeing yourself honestly, without being harsh about it', 'If you had to describe yourself with no filter and no put-downs, what would you say?', 'Stories and identity', '2 of 5', '2, 25, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (5, 'Teen', 1, 'See Clearly', false, 'The Mirror — How We See Ourselves', 'The Comparison Trap and the Real Mirror', 'There''s an old story about a young warrior who keeps losing battles because he''s fighting the wrong enemy — his own reflection, which he mistakes for an opponent. The battles with ourselves, the harsh self-judgments, the impossible standards — most of the time, we''re fighting a distorted image, not reality.', 'There''s an old story about a young warrior who keeps losing battles because he''s fighting the wrong enemy — his own reflection, which he mistakes for an opponent.', '', '', 'The front camera shows every flaw; a good friend''s photo catches you laughing — self-awareness is choosing the friend''s lens. Today: describe yourself the way someone who loves you would.', 'The front camera shows every flaw; a good friend''s photo catches you laughing — self-awareness is choosing the friend''s lens.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (6, 1, 'See Clearly', 'The Comparison Loop', 'See Clearly', 'Comparing your real life to someone else''s highlights', 'Who do you compare yourself to, and what do you think they''ve got?', 'Enough', '1 of 3', '20, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (6, 'Teen', 1, 'See Clearly', false, 'The Comparison Loop', 'The Race With the Moving Finish Line', 'There''s an old idea: ''The candle that burns next to the sun looks dim — but light up a dark room and it''s extraordinary.'' Your life is not measured against the sun. It is measured against the darkness you chose to show up for.', 'There''s an old idea: ''The candle that burns next to the sun looks dim — but light up a dark room and it''s extraordinary.'' Your life is not…', '', '', 'Scrolling compares your behind-the-scenes to everyone''s highlight reel — a treadmill where you sweat and never move. Today: name one ''race'' you''re quitting and mute the feed that runs it.', 'Scrolling compares your behind-the-scenes to everyone''s highlight reel — a treadmill where you sweat and never move.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (7, 1, 'See Clearly', 'The Inner Critic', 'See Clearly', 'The voice in your head that talks to you worse than anyone else does', 'If that voice was a person in your group chat, would you keep them in it?', 'The inner voice', '1 of 3', '18, 32', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (7, 'Teen', 1, 'See Clearly', false, 'The Inner Critic', 'Introducing the Heckler', 'In martial arts there''s a principle: you don''t fight your shadow. You can''t. The shadow isn''t an enemy — it''s just the shape of the light you''re blocking. The inner critic is similar. Fighting it directly makes it stronger. What works is shining more light.', 'In martial arts there''s a principle: you don''t fight your shadow. You can''t. The shadow isn''t an enemy — it''s just the shape of the light you''re blocking.', '', '', 'The inner critic is a group chat in your head that only ever roasts you — you can mute it and add a coach who''s honest but kind. Today: when the roast fires, ask ''would I say this to my best mate?''', 'The inner critic is a group chat in your head that only ever roasts you — you can mute it and add a coach who''s honest but kind.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (8, 1, 'See Clearly', 'Beneath the Surface — Emotions as Data', 'See Clearly', 'The feeling that was there before the one you noticed', 'What were you actually feeling right before you got angry?', 'Emotions as data', '1 of 3', '24, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (8, 'Teen', 1, 'See Clearly', false, 'Beneath the Surface — Emotions as Data', 'Optimising the Notification System', 'The samurai tradition had a concept called zanshin — a state of total awareness, including of one''s own emotional state. Not the absence of emotion — full awareness of it. The warrior disconnected from their own emotional state is the most dangerous — not because they feel nothing, but because they act without knowing what they''re feeling. Emotional intelligence was never considered weakness. It was considered mastery.', 'The samurai tradition had a concept called zanshin — a state of total awareness, including of one''s own emotional state.', '', '', 'Anger is just the app icon; tap it and the real feeling opens underneath — fear, hurt, tiredness. Today: next time you''re ''grumpy'', open the icon and read what''s actually inside.', 'Anger is just the app icon; tap it and the real feeling opens underneath — fear, hurt, tiredness.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (9, 1, 'See Clearly', 'The Wounds We Carry', 'See Clearly', 'Things that hurt, and what happens when you never say them out loud', 'What happened to you that you''ve never really talked about?', 'Old hurt', '1 of 3', '21, 23', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (9, 'Teen', 1, 'See Clearly', true, 'The Wounds We Carry', 'The Update Nobody Installed on Purpose', 'There''s an idea held in many cultures: that the greatest strength doesn''t come from having no wounds. It comes from knowing your wounds — their shape, their history, what they''ve made of you — and continuing anyway. The mark of wisdom is not invulnerability. It is honest, courageous self-knowledge.', 'There''s an idea held in many cultures: that the greatest strength doesn''t come from having no wounds.', '', '', 'Old hurts are a heavy backpack you''ve worn so long you forgot it''s on — naming them in a safe room is setting it down for a minute. Today: name one thing you''ve been carrying, just to feel the weight lift.', 'Old hurts are a heavy backpack you''ve worn so long you forgot it''s on — naming them in a safe room is setting it down for a minute.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (10, 1, 'See Clearly', 'The Masks We Wear', 'See Clearly', 'The version of you online and at school, and the one nobody sees', 'Is there something about you that you''ve never let anyone see?', 'Masks and being seen', '1 of 3', '22, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (10, 'Teen', 1, 'See Clearly', false, 'The Masks We Wear', 'Which One Is Actually You?', 'There''s an old concept from theatre: the mask was always meant to serve the story — and when the play is over, it comes off. The problem we''re exploring today is what happens when the play never ends, and you start to forget you''re even wearing a mask.', 'There''s an old concept from theatre: the mask was always meant to serve the story — and when the play is over, it comes off.', '', '', 'Your profile is the filtered photo; the real you is the whole camera roll — and the right people want the camera roll. Today: show one true, unfiltered thing to someone safe.', 'Your profile is the filtered photo; the real you is the whole camera roll — and the right people want the camera roll.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (11, 1, 'See Clearly', 'Seeing Others Clearly', 'See Clearly', 'What might be going on for someone before they were rude to you', 'Think of someone who annoys you. What might be going on for them?', 'Seeing others', '1 of 3', '44, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (11, 'Teen', 1, 'See Clearly', false, 'Seeing Others Clearly', 'Turning Down the Projector', 'There''s an old practice in many traditions of deep listening — so complete that for a moment, you put your own perspective fully aside and inhabit someone else''s. It''s one of the rarest and most valuable skills a person can develop. And it starts with noticing how much you''re not currently doing it.', 'There''s an old practice in many traditions of deep listening — so complete that for a moment, you put your own perspective fully aside and inhabit someone else''s.', '', '', 'Everyone''s driving with a dashcam you can''t see — the person who cut you off might be racing to a hospital. Today: give one person the benefit of their unseen story.', 'Everyone''s driving with a dashcam you can''t see — the person who cut you off might be racing to a hospital.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (12, 1, 'See Clearly', 'The Habit Loop — How We Got Here', 'See Clearly', 'The stuff you do automatically without ever choosing it', 'What do you always do when you''re stressed, without even deciding to?', 'Habits and structure', '1 of 4', '29, 33, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (12, 'Teen', 1, 'See Clearly', false, 'The Habit Loop — How We Got Here', 'Understanding Autopilot', 'Water always flows downhill — not because it''s lazy, but because that''s its nature. Trying to make water go uphill by force is exhausting and temporary. Understanding the terrain and working with it is how you get the water where you want it. Habits work the same way.', 'Water always flows downhill — not because it''s lazy, but because that''s its nature. Trying to make water go uphill by force is exhausting and temporary.', '', '', 'A habit is an autoplay playlist — one trigger and the next track just starts. Today: spot the trigger track for one habit and swap the next song on purpose.', 'A habit is an autoplay playlist — one trigger and the next track just starts.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (13, 1, 'See Clearly', 'Integration — What We Now See', 'See Clearly', 'Pulling the last thirteen weeks together', 'What have you worked out about yourself this term?', 'Integration', '1 of 4', '26, 39, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (13, 'Teen', 1, 'See Clearly', false, 'Integration — What We Now See', 'The Diagnostic Is Complete', 'In many traditions a period of learning is marked by a rite of passage — not because you''re now ''done,'' but because something real has changed and it deserves to be acknowledged. You''ve looked at things most people spend their whole lives avoiding. That matters.', 'In many traditions a period of learning is marked by a rite of passage — not because you''re now ''done,'' but because something real has changed and it…', '', '', 'You''ve been handed a toolkit — a pause button, a feelings-iceberg, a mirror, a mute button for the critic. Today: pick the one tool you''ll actually keep in your pocket.', 'You''ve been handed a toolkit — a pause button, a feelings-iceberg, a mirror, a mute button for the critic.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (14, 2, 'Unlearn', 'The Permission You''re Still Waiting For', 'Unlearn', 'Waiting for someone to say it''s okay', 'What are you waiting for permission to do?', 'Permission and values', '1 of 4', '15, 28, 43', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (14, 'Teen', 2, 'Unlearn', false, 'The Permission You''re Still Waiting For', 'Admin Access Granted', 'There''s an old story about a student who kept asking their teacher for permission to begin. The teacher kept saying ''not yet.'' Eventually the student realised: the teacher wasn''t the one who could give that permission. Nobody was. The moment they began without asking, that was the lesson.', 'There''s an old story about a student who kept asking their teacher for permission to begin.', '', '', 'You keep refreshing an inbox for an approval email that''s never coming — because you''re the one who has to hit send. Today: give yourself the green light on one thing you''ve been waiting on.', 'You keep refreshing an inbox for an approval email that''s never coming — because you''re the one who has to hit send.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (15, 2, 'Unlearn', 'Letting Go of Who You Were Supposed to Be', 'Unlearn', 'Living up to what everyone expects', 'Whose expectations are you living inside?', 'Permission and values', '2 of 4', '14, 28, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (15, 'Teen', 2, 'Unlearn', false, 'Letting Go of Who You Were Supposed to Be', 'Default Settings', 'There''s an old idea: ''The life that is not examined is not worth living.'' But what''s rarely said is the other side — the life lived entirely according to someone else''s examination, someone else''s conclusions, someone else''s expectations — that''s not really living either. Today we start examining.', 'There''s an old idea: ''The life that is not examined is not worth living.'' But what''s rarely said is the other side — the life lived entirely according…', '', '', 'You''ve been reading lines off a teleprompter someone else wrote — but it isn''t your story. Today: put down one ''should'' and say the line that''s actually yours.', 'You''ve been reading lines off a teleprompter someone else wrote — but it isn''t your story. Today: put down one ''should'' and say the line that''s actually yours.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (16, 2, 'Unlearn', 'The Forgiveness Loop', 'Unlearn', 'Staying angry at someone, and what it costs you', 'Who are you still angry at, and what does staying angry give you?', 'Forgiveness', '1 of 3', '17, 45', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (16, 'Teen', 2, 'Unlearn', true, 'The Forgiveness Loop', 'Closing the Background Apps', 'There''s an old saying: ''Holding onto anger is like drinking poison and expecting the other person to die.'' Most traditions across the world arrived at the same conclusion independently: forgiveness is not for the person who wronged you. It is for you.', 'There''s an old saying: ''Holding onto anger is like drinking poison and expecting the other person to die.'' Most traditions across the world arrived at the same conclusion…', '', '', 'Resentment is gripping a hot coal to throw at someone — you''re the one getting burned. Today: name one grudge and picture opening your hand and setting the coal down.', 'Resentment is gripping a hot coal to throw at someone — you''re the one getting burned.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (17, 2, 'Unlearn', 'Forgiving Yourself', 'Unlearn', 'Being honest about a mistake without hating yourself for it', 'What have you done that you still haven''t forgiven yourself for?', 'Forgiveness', '2 of 3', '16, 45', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (17, 'Teen', 2, 'Unlearn', true, 'Forgiving Yourself', 'Closing the 2am Replay', 'There''s an old practice in many wisdom traditions of ''honest confession'' — not to a religious authority, but to yourself. The practice wasn''t about punishment. It was about seeing clearly, accepting responsibility, and then releasing the grip of the past on the present. The purpose was always freedom, not continued suffering.', 'There''s an old practice in many wisdom traditions of ''honest confession'' — not to a religious authority, but to yourself. The practice wasn''t about punishment.', '', '', 'You wouldn''t keep charging a friend for a debt they already paid — so stop billing yourself for the same mistake. Today: mark one thing ''paid — lesson kept'' and close the account.', 'You wouldn''t keep charging a friend for a debt they already paid — so stop billing yourself for the same mistake.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (18, 2, 'Unlearn', 'Rewiring the Critic — Building the Inner Coach', 'Unlearn', 'Turning the harsh voice into an honest one', 'What would a good coach have said to you instead?', 'The inner voice', '2 of 3', '7, 32', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (18, 'Teen', 2, 'Unlearn', false, 'Rewiring the Critic — Building the Inner Coach', 'Building the Track', 'There''s a difference between a trainer who pushes you to get better and a voice that just tells you you''re not good enough. One builds capacity. The other just builds dread. The inner coach pushes — but it believes in you while it does. That combination is what makes it work.', 'There''s a difference between a trainer who pushes you to get better and a voice that just tells you you''re not good enough. One builds capacity.', '', '', 'Swap the heckler in your head for a good coach — same honesty, opposite tone. Today: rewrite one harsh line the way a great coach would say it.', 'Swap the heckler in your head for a good coach — same honesty, opposite tone. Today: rewrite one harsh line the way a great coach would say it.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (19, 2, 'Unlearn', 'Breaking the People-Pleasing Pattern', 'Unlearn', 'Being nice because you''re scared, versus being nice because you mean it', 'When did you last say yes when you really meant no?', 'Choice and response', '2 of 3', '3, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (19, 'Teen', 2, 'Unlearn', false, 'Breaking the People-Pleasing Pattern', 'The Battery Drain', 'There''s an old idea: you can''t pour from an empty cup. People-pleasing is the habit of pouring constantly — for everyone else — and wondering why you''re always running on empty. The radical act is filling your own cup first. Not instead of caring for others. But before.', 'There''s an old idea: you can''t pour from an empty cup.', '', '', 'Saying yes to everything is never closing any apps — your battery hits 1% by noon; a boundary is low-power mode on purpose. Today: turn one fear-''yes'' into an honest ''no''.', 'Saying yes to everything is never closing any apps — your battery hits 1% by noon; a boundary is low-power mode on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (20, 2, 'Unlearn', 'Unlearning Scarcity — There Is Enough', 'Unlearn', 'The feeling that there isn''t enough to go around', 'What do you hold back on, just in case?', 'Enough', '2 of 3', '6, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (20, 'Teen', 2, 'Unlearn', false, 'Unlearning Scarcity — There Is Enough', 'The Resource Monitor', 'There''s an old observation: ''The one who knows they have enough will always have enough.'' This isn''t about money or stuff. It''s about the baseline belief you carry. If the baseline is ''there isn''t enough'' — you''ll feel that scarcity even when you''re objectively fine. If the baseline is ''there is enough'' — you generate more of everything.', 'There''s an old observation: ''The one who knows they have enough will always have enough.'' This isn''t about money or stuff. It''s about the baseline belief you carry.', '', '', 'Kindness isn''t a biscuit tin that empties — it''s a candle that lights other candles and loses nothing. Today: give something away as if it multiplies, because it does.', 'Kindness isn''t a biscuit tin that empties — it''s a candle that lights other candles and loses nothing.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (21, 2, 'Unlearn', 'The Relationships That Shaped You', 'Unlearn', 'What you picked up from the people who raised you', 'What did you learn about love from the people who raised you?', 'Old hurt', '2 of 3', '9, 23', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (21, 'Teen', 2, 'Unlearn', true, 'The Relationships That Shaped You', 'Auditing the Relationship Code', 'There''s an old observation: ''Show me who shaped you and I''ll understand how you love.'' Not as a verdict — but as a map. Understanding where your relational patterns came from is the beginning of choosing which ones to carry forward.', 'There''s an old observation: ''Show me who shaped you and I''ll understand how you love.'' Not as a verdict — but as a map.', '', '', 'You inherited relationship ''settings'' the way a phone ships with defaults — some are great, some need updating. Today: spot one default about love you want to change.', 'You inherited relationship ''settings'' the way a phone ships with defaults — some are great, some need updating. Today: spot one default about love you want to change.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (22, 2, 'Unlearn', 'Setting Down the Armour', 'Unlearn', 'The walls that kept you safe and now keep people out', 'What are you protecting, and who''s stuck on the outside of it?', 'Masks and being seen', '2 of 3', '10, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (22, 'Teen', 2, 'Unlearn', false, 'Setting Down the Armour', 'Firewall Settings', 'There''s an old paradox: the strongest walls also keep out the light. Protecting yourself from pain often protects you from joy in the same motion. The question is not whether to have walls — but knowing where the doors are, and trusting yourself to choose when to open them.', 'There''s an old paradox: the strongest walls also keep out the light. Protecting yourself from pain often protects you from joy in the same motion.', '', '', 'The armour that got you through school now sets off the metal detector at the hug. Today: lower one piece of armour — sarcasm, busyness, control — with one safe person.', 'The armour that got you through school now sets off the metal detector at the hug.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (23, 2, 'Unlearn', 'Grief and Growth — What Endings Make Possible', 'Unlearn', 'Endings, and what they make room for', 'What ended that you never really got over?', 'Old hurt', '3 of 3', '9, 21', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (23, 'Teen', 2, 'Unlearn', true, 'Grief and Growth — What Endings Make Possible', 'What Deserved a Ceremony', 'There''s an old understanding across cultures: endings deserve to be witnessed. That''s why there are funerals, closing ceremonies, graduation rituals. The ritual isn''t for the dead — it''s for the living. It marks the ending so the living can begin. Today we think about the endings in your life that deserved a ceremony and didn''t get one.', 'There''s an old understanding across cultures: endings deserve to be witnessed. That''s why there are funerals, closing ceremonies, graduation rituals.', '', '', 'Winter looks like the tree died, but it''s just clearing the branches for spring. Today: name what an ending has quietly made room for.', 'Winter looks like the tree died, but it''s just clearing the branches for spring. Today: name what an ending has quietly made room for.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (24, 2, 'Unlearn', 'Rewiring Fear — From Threat to Signal', 'Unlearn', 'Fear as information, not an instruction', 'What are you scared of that has never actually happened?', 'The body', '2 of 3', '4, 30', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (24, 'Teen', 2, 'Unlearn', true, 'Rewiring Fear — From Threat to Signal', 'Updating the Alarm System', 'There''s an old practice: the samurai meditated on death daily — not to become morbid, but to distinguish clearly between what was actually dangerous and what merely felt uncomfortable. The distinction gave them freedom. Most of our fears, when examined clearly, turn out to be discomfort wearing a danger costume.', 'There''s an old practice: the samurai meditated on death daily — not to become morbid, but to distinguish clearly between what was actually dangerous and what merely felt…', '', '', 'Most alarms in your head are burnt toast, not a house fire — the smoke detector just can''t tell the difference. Today: label one fear ''burnt toast'' and open a window instead of running.', 'Most alarms in your head are burnt toast, not a house fire — the smoke detector just can''t tell the difference.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (25, 2, 'Unlearn', 'The Stories That No Longer Serve', 'Unlearn', 'An old story that protected you and now holds you back', 'What story about yourself is out of date?', 'Stories and identity', '3 of 5', '2, 5, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (25, 'Teen', 2, 'Unlearn', false, 'The Stories That No Longer Serve', 'Writing the Update', 'There''s a real difference between the events of your life and the story you tell about those events. The events are fixed. The story is not. You are always the author of the meaning. Today we practise using that authorship.', 'There''s a real difference between the events of your life and the story you tell about those events. The events are fixed. The story is not.', '', '', 'An old story is a saved route on your maps app that no longer goes where you live. Today: delete one outdated ''I always…'' and set a new destination.', 'An old story is a saved route on your maps app that no longer goes where you live.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (26, 2, 'Unlearn', 'Integration — What We Have Released', 'Unlearn', 'Pulling the movement together', 'What have you put down, and what are you still holding?', 'Integration', '2 of 4', '13, 39, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (26, 'Teen', 2, 'Unlearn', false, 'Integration — What We Have Released', 'Threshold Crossing', 'In old traditions, a period of inner work was always marked with a ceremony — a threshold crossing. Not because you''re done. Because something real has happened, and it deserves to be acknowledged. That''s today.', 'In old traditions, a period of inner work was always marked with a ceremony — a threshold crossing. Not because you''re done.', '', '', 'You''ve cleared a pile of old apps clogging the phone — permission-seeking, resentment, armour. Today: notice how much lighter and faster you run without them.', 'You''ve cleared a pile of old apps clogging the phone — permission-seeking, resentment, armour. Today: notice how much lighter and faster you run without them.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (27, 3, 'Rebuild', 'Who Are You Now? — Rebuilding Identity', 'Rebuild', 'Choosing who you are instead of accepting a label', 'If nobody had ever told you who you were, who would you be?', 'Stories and identity', '4 of 5', '2, 5, 25, 49', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (27, 'Teen', 3, 'Rebuild', false, 'Who Are You Now? — Rebuilding Identity', 'The First Brick', 'There''s an old idea that the most important question a person can ask is not ''what do I want to do?'' but ''who do I want to be?'' Because who you are shapes everything you do. Today we start answering that question from scratch — without the old stories running the answer.', 'There''s an old idea that the most important question a person can ask is not ''what do I want to do?'' but ''who do I want to be?''…', '', '', 'Instead of the labels stuck on you like airport baggage tags, you get to pack your own bag. Today: choose the three qualities you''re building yourself from.', 'Instead of the labels stuck on you like airport baggage tags, you get to pack your own bag. Today: choose the three qualities you''re building yourself from.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (28, 3, 'Rebuild', 'What Do You Actually Value?', 'Rebuild', 'What actually matters to you underneath the goals', 'What would you not give up, whatever you were offered?', 'Permission and values', '3 of 4', '14, 15, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (28, 'Teen', 3, 'Rebuild', false, 'What Do You Actually Value?', 'Opening the Settings Menu', 'There''s a powerful question from philosophy: ''How do you want to live?'' Not what do you want to have or achieve — but how do you want to live? What qualities do you want to be true of how you show up every day? That question is the beginning of values. Today we answer it.', 'There''s a powerful question from philosophy: ''How do you want to live?'' Not what do you want to have or achieve — but how do you want to…', '', '', 'Values are your GPS ''home'' setting — every turn is easier once it''s locked in. Today: name your true-north value and check one recent decision against it.', 'Values are your GPS ''home'' setting — every turn is easier once it''s locked in. Today: name your true-north value and check one recent decision against it.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (29, 3, 'Rebuild', 'The Habits That Build You', 'Rebuild', 'Small things done daily that build who you become', 'What do you do every day that''s quietly making you someone?', 'Habits and structure', '2 of 4', '12, 33, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (29, 'Teen', 3, 'Rebuild', false, 'The Habits That Build You', 'Designing the Practice', 'Small consistent practice beats large inconsistent effort every time. Not dramatic. Just regular. The river doesn''t carve the canyon in one rush — it does it through constant, patient movement in one direction. That''s the practice.', 'Small consistent practice beats large inconsistent effort every time. Not dramatic. Just regular.', '', '', 'You don''t get fit from one epic gym session — you get fit from showing up small and often; identity works the same. Today: pick the 1% habit you''ll repeat like brushing your teeth.', 'You don''t get fit from one epic gym session — you get fit from showing up small and often; identity works the same.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (30, 3, 'Rebuild', 'Your Body as Foundation', 'Rebuild', 'Sleep, food, movement — the base everything sits on', 'What does your body need that you keep ignoring?', 'The body', '3 of 3', '4, 24', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (30, 'Teen', 3, 'Rebuild', false, 'Your Body as Foundation', 'Charging the Hardware', 'Ancient warriors, scholars, and sages all had one thing in common: they treated the body with deliberate respect. Not vanity. Not performance. Foundation. The body carries the mind carries the soul — and they cannot be separated. What you do for your body, you do for everything else.', 'Ancient warriors, scholars, and sages all had one thing in common: they treated the body with deliberate respect. Not vanity. Not performance. Foundation.', '', '', 'Your body is the phone the whole day runs on, and sleep, movement, food and calm are the four charging cables. Today: plug in the one that''s most drained.', 'Your body is the phone the whole day runs on, and sleep, movement, food and calm are the four charging cables.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (31, 3, 'Rebuild', 'The People You Choose', 'Rebuild', 'How the people around you shape who you are', 'Who do you become when you''re with your closest mates?', 'Belonging', '1 of 3', '38, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (31, 'Teen', 3, 'Rebuild', false, 'The People You Choose', 'Your Operating Environment', 'There''s an old observation: ''If you want to fly with eagles, don''t hang around with turkeys.'' Not about judgment — about environment. The people you surround yourself with set the standard for what''s possible, what''s normal, and who you''re becoming. That''s worth being intentional about.', 'There''s an old observation: ''If you want to fly with eagles, don''t hang around with turkeys.'' Not about judgment — about environment.', '', '', 'You become the average of your five most-opened contacts. Today: pick one relationship to open more, and one notification to turn down.', 'You become the average of your five most-opened contacts. Today: pick one relationship to open more, and one notification to turn down.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (32, 3, 'Rebuild', 'How You Speak to Yourself', 'Rebuild', 'How you talk to yourself when things go wrong', 'What would you say to a mate who was where you are?', 'The inner voice', '3 of 3', '7, 18', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (32, 'Teen', 3, 'Rebuild', false, 'How You Speak to Yourself', 'Redesigning the Soundtrack', 'There''s a concept in coaching: the quality of your self-talk determines the quality of your performance — not as motivation, but as neuroscience. The words you use internally trigger physiological responses. Choose them like it matters. Because it does.', 'There''s a concept in coaching: the quality of your self-talk determines the quality of your performance — not as motivation, but as neuroscience.', '', '', 'Talk to yourself like you''d text a friend having a hard day — not like an anonymous troll in the comments. Today: keep one kind phrase in your pocket for the next hard moment.', 'Talk to yourself like you''d text a friend having a hard day — not like an anonymous troll in the comments.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (33, 3, 'Rebuild', 'Creating Structure That Serves You', 'Rebuild', 'Routine as a support, not a cage', 'What in your week is helping you, and what''s just habit?', 'Habits and structure', '3 of 4', '12, 29, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (33, 'Teen', 3, 'Rebuild', false, 'Creating Structure That Serves You', 'Designing the Container', 'Great athletes, musicians, and creators all have daily structures — not because they''re rigid, but because structure frees them from having to decide everything constantly, which means they have more energy for what matters. The discipline creates the freedom. Today we experience that.', 'Great athletes, musicians, and creators all have daily structures — not because they''re rigid, but because structure frees them from having to decide everything constantly, which means they…', '', '', 'Routine isn''t a cage — it''s the trellis a plant climbs to reach the light. Today: add one small anchor (same wake time, one blocked hour) and let freedom grow on it.', 'Routine isn''t a cage — it''s the trellis a plant climbs to reach the light.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (34, 3, 'Rebuild', 'Rest as a Practice, Not a Reward', 'Rebuild', 'Rest you don''t have to earn', 'When did you last properly rest and not feel guilty?', 'Signal and attention', '2 of 4', '1, 50, 51', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (34, 'Teen', 3, 'Rebuild', false, 'Rest as a Practice, Not a Reward', 'The Recovery Protocol', 'Ancient cultures all knew this: work and rest are a cycle, not a competition. Every tradition that has produced sustained human excellence has had deliberate rest built in. Not as weakness. As wisdom.', 'Ancient cultures all knew this: work and rest are a cycle, not a competition. Every tradition that has produced sustained human excellence has had deliberate rest built in.', '', '', 'You plug your phone in before it dies, not after — do the same for yourself. Today: schedule one real rest block before you''re down to 1%.', 'You plug your phone in before it dies, not after — do the same for yourself. Today: schedule one real rest block before you''re down to 1%.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (35, 3, 'Rebuild', 'Creativity and Expression', 'Rebuild', 'Making things because you want to, not because you''re good at it', 'What did you love making before someone told you if you were good at it?', 'Creativity and expression', '1 of 3', '41, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (35, 'Teen', 3, 'Rebuild', false, 'Creativity and Expression', 'Making Without Judging', 'There is a version of you that makes things just because they feel true — not for an audience, not for likes, not to prove anything. That version hasn''t gone anywhere. It''s just waiting for permission to exist without being judged. This week we give that permission.', 'There is a version of you that makes things just because they feel true — not for an audience, not for likes, not to prove anything.', '', '', 'Making something is like cooking for yourself — it doesn''t need a Michelin star to feed you. Today: make one small thing no one will grade.', 'Making something is like cooking for yourself — it doesn''t need a Michelin star to feed you. Today: make one small thing no one will grade.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (36, 3, 'Rebuild', 'Purpose — What You''re Here For', 'Rebuild', 'Where what you''re good at meets what''s needed', 'What are you doing when you lose track of time?', 'Purpose', '1 of 3', '40, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (36, 'Teen', 3, 'Rebuild', false, 'Purpose — What You''re Here For', 'Finding the Direction', 'There''s an old Japanese concept called ikigai — which roughly means ''reason for being.'' It''s not about having everything figured out. It''s about finding the space where what you love, what you''re good at, and what the world needs overlap. Today we map that space.', 'There''s an old Japanese concept called ikigai — which roughly means ''reason for being.'' It''s not about having everything figured out.', '', '', 'Purpose is where your skills and the world''s needs overlap — the sweet spot of the Venn diagram. Today: name one small place that overlap already exists.', 'Purpose is where your skills and the world''s needs overlap — the sweet spot of the Venn diagram. Today: name one small place that overlap already exists.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (37, 3, 'Rebuild', 'Money, Abundance and Your Relationship With Resources', 'Rebuild', 'What you picked up about money before you could question it', 'What did you learn about money growing up?', 'Resources', '2 of 3', '20, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (37, 'Teen', 3, 'Rebuild', false, 'Money, Abundance and Your Relationship With Resources', 'What You''ve Inherited About Resources', 'There''s an old idea: ''The way you do anything is the way you do everything.'' Your relationship with money is a mirror of your relationship with abundance, scarcity, worthiness, and what you believe you deserve. Today we look in that mirror.', 'There''s an old idea: ''The way you do anything is the way you do everything.'' Your relationship with money is a mirror of your relationship with abundance, scarcity…', '', '', 'Your money ''scripts'' are inherited apps running in the background of every purchase. Today: sort one thing into need / want / could-share and notice which script ran.', 'Your money ''scripts'' are inherited apps running in the background of every purchase. Today: sort one thing into need / want / could-share and notice which script ran.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (38, 3, 'Rebuild', 'The Community You Build', 'Rebuild', 'Being part of something and bringing something to it', 'What do you bring that a room is worse without?', 'Belonging', '2 of 3', '31, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (38, 'Teen', 3, 'Rebuild', false, 'The Community You Build', 'Building Real Connection', 'The most important thing the research on human happiness has found is this: the quality of your relationships is the single strongest predictor of how happy and healthy you''ll be. Not your grades, not your future career, not your success. Your relationships. That''s worth building deliberately.', 'The most important thing the research on human happiness has found is this: the quality of your relationships is the single strongest predictor of how happy and healthy…', '', '', 'A community is a beehive — it works because everyone brings something back. Today: name the one thing you''ll bring to a room you want to belong to.', 'A community is a beehive — it works because everyone brings something back. Today: name the one thing you''ll bring to a room you want to belong to.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (39, 3, 'Rebuild', 'Integration — Who You Are Becoming', 'Rebuild', 'Pulling the movement together', 'What''s different about how you live now?', 'Integration', '3 of 4', '13, 26, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (39, 'Teen', 3, 'Rebuild', false, 'Integration — Who You Are Becoming', 'What Has Been Built', 'The foundation is laid. Not perfect — laid. And the most important thing about a foundation is not that it''s complete. It''s that it''s genuinely there, genuinely yours, and genuinely strong enough to build on.', 'The foundation is laid. Not perfect — laid. And the most important thing about a foundation is not that it''s complete.', '', '', 'The building site is now a home you can live in — identity, values, habits, people. Today: name who you''ve become, and step through the door into living it.', 'The building site is now a home you can live in — identity, values, habits, people.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (40, 4, 'Live It', 'From Self-Development to Service', 'Live It', 'What all this work is actually for', 'Who''s better off because of the work you''ve done this year?', 'Purpose', '2 of 3', '36, 49', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (40, 'Teen', 4, 'Live It', false, 'From Self-Development to Service', 'Pointing the Torch Outward', 'There''s an old idea: you cannot carry a torch for yourself alone. Light is most itself when it illuminates something. The work of this year has lit something in you. Phase 4 is pointing it outward.', 'There''s an old idea: you cannot carry a torch for yourself alone. Light is most itself when it illuminates something.', '', '', 'You don''t hoard the wifi password once you''re connected — you share it; inner work is the same. Today: give one thing you''ve healed enough to offer someone else.', 'You don''t hoard the wifi password once you''re connected — you share it; inner work is the same.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (41, 4, 'Live It', 'Teaching What You''ve Learned', 'Live It', 'Understanding something twice by explaining it to someone', 'What do you know now that you wish someone had told you?', 'Creativity and expression', '2 of 3', '35, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (41, 'Teen', 4, 'Live It', false, 'Teaching What You''ve Learned', 'Learning by Giving It Away', 'There''s an old saying: to teach is to learn twice. When you put something into words for another person, you have to understand it well enough to make it clear to someone who doesn''t yet. That process deepens your own understanding more than any amount of studying alone.', 'There''s an old saying: to teach is to learn twice.', '', '', 'Explaining something to a ten-year-old is how you find out you actually understand it. Today: put one lesson into one plain sentence and pass it on.', 'Explaining something to a ten-year-old is how you find out you actually understand it. Today: put one lesson into one plain sentence and pass it on.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (42, 4, 'Live It', 'The Courage to Be Seen', 'Live It', 'Being properly seen, and what''s on the other side of the fear', 'What''s true about you that you''ve never let anyone see?', 'Masks and being seen', '3 of 3', '10, 22', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (42, 'Teen', 4, 'Live It', true, 'The Courage to Be Seen', 'Closing the Gap', 'Here''s the thing about being seen: you cannot be genuinely connected to people who only know your performance. Genuine connection requires genuine presence. And genuine presence requires courage. The courage to let people see who you actually are.', 'Here''s the thing about being seen: you cannot be genuinely connected to people who only know your performance. Genuine connection requires genuine presence. And genuine presence requires courage.', '', '', 'Turning your camera on in the meeting is scary for two seconds and connecting for the rest. Today: show up ''camera-on'' in one place you usually hide.', 'Turning your camera on in the meeting is scary for two seconds and connecting for the rest. Today: show up ''camera-on'' in one place you usually hide.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (43, 4, 'Live It', 'Living Your Values Under Pressure', 'Live It', 'What holds when it costs you something', 'When did you last go against what you believe because of pressure?', 'Emotions as data', '3 of 3', '8, 24', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (43, 'Teen', 4, 'Live It', false, 'Living Your Values Under Pressure', 'The Pressure Test', 'Here''s the truth about values: everyone has them in good times. The people who genuinely live their values are the ones who practise holding them when it''s uncomfortable. Not perfectly. Just consistently. That consistency is what builds real character.', 'Here''s the truth about values: everyone has them in good times. The people who genuinely live their values are the ones who practise holding them when it''s uncomfortable.', '', '', 'Your values are only real in the storm, not the sunshine — like a compass that has to work when the sky goes dark. Today: name one value you''ll hold even when it costs you.', 'Your values are only real in the storm, not the sunshine — like a compass that has to work when the sky goes dark.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (44, 4, 'Live It', 'Conflict as a Growth Practice', 'Live It', 'Staying in an argument instead of walking away from it', 'What argument have you been avoiding, and what are you protecting?', 'Seeing others', '2 of 3', '11, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (44, 'Teen', 4, 'Live It', false, 'Conflict as a Growth Practice', 'Needs, Not Positions', 'There is an ancient practice: before you argue about what you want, name what you need. Not the position — the underlying need. When two people can hear each other''s needs — really hear them — most conflicts turn out to be much more solvable than they looked.', 'There is an ancient practice: before you argue about what you want, name what you need. Not the position — the underlying need.', '', '', '''You always…'' starts a fight; ''I feel… I need…'' starts a conversation. Today: rewrite one hard message in the second language.', '''You always…'' starts a fight; ''I feel… I need…'' starts a conversation. Today: rewrite one hard message in the second language.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (45, 4, 'Live It', 'Generosity as a Way of Being', 'Live It', 'Giving in a way that doesn''t drain you', 'What do you give that costs you nothing and means a lot to someone?', 'Forgiveness', '3 of 3', '16, 17', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (45, 'Teen', 4, 'Live It', false, 'Generosity as a Way of Being', 'Open Hands', 'An open hand can give AND receive. A closed fist can do neither. Generosity is the practice of keeping your hands open — not because you have unlimited resources, but because openness is a better orientation than protection.', 'An open hand can give AND receive. A closed fist can do neither.', '', '', 'Some gifts — encouragement, time, attention — cost nothing and still glow in your own hands after you give them. Today: give one non-money gift by Sunday.', 'Some gifts — encouragement, time, attention — cost nothing and still glow in your own hands after you give them. Today: give one non-money gift by Sunday.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (46, 4, 'Live It', 'Enough — Living From Sufficiency', 'Live It', 'Noticing what''s already good', 'What''s already enough that you keep treating like it isn''t?', 'Enough', '3 of 3', '6, 20', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (46, 'Teen', 4, 'Live It', false, 'Enough — Living From Sufficiency', 'Starting From Here', 'There''s an old idea: ''Enough is a feast.'' Not in the sense of having everything — in the sense of being fully present to what is already here. Today we practise that presence.', 'There''s an old idea: ''Enough is a feast.'' Not in the sense of having everything — in the sense of being fully present to what is already here.', '', '', 'The ''add to cart'' feeling is a treadmill — one more thing never becomes enough. Today: name three things you already have that are genuinely enough.', 'The ''add to cart'' feeling is a treadmill — one more thing never becomes enough. Today: name three things you already have that are genuinely enough.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (47, 4, 'Live It', 'The Long Game — Patience and Persistence', 'Live It', 'Progress you can''t see yet', 'What are you working at that hasn''t shown yet?', 'Habits and structure', '4 of 4', '12, 29, 33', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (47, 'Teen', 4, 'Live It', false, 'The Long Game — Patience and Persistence', 'Compound Interest for a Person', 'There''s an old idea: ''The best time to plant a tree was twenty years ago. The second best time is today.'' The long game is not about when you started. It is about whether you keep going. Today we decide to keep going.', 'There''s an old idea: ''The best time to plant a tree was twenty years ago.', '', '', 'A seed spends weeks looking like nothing while it grows roots — don''t dig it up to check. Today: recommit to one slow, unglamorous thing that''s still growing underground.', 'A seed spends weeks looking like nothing while it grows roots — don''t dig it up to check.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (48, 4, 'Live It', 'Leaving People Better Than You Found Them', 'Live It', 'Small moments that go further than you think', 'Who left you better than they found you?', 'Seeing others', '3 of 3', '11, 44', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (48, 'Teen', 4, 'Live It', false, 'Leaving People Better Than You Found Them', 'One Question', 'There''s a question worth carrying: ''Will this person be slightly better for having encountered me today?'' Not dramatically better — just slightly. That question, asked consistently, changes how you show up to everything.', 'There''s a question worth carrying: ''Will this person be slightly better for having encountered me today?'' Not dramatically better — just slightly.', '', '', 'You leave a ''tip'' in every interaction — a little brighter or a little dimmer. Today: leave one person brighter, on purpose.', 'You leave a ''tip'' in every interaction — a little brighter or a little dimmer. Today: leave one person brighter, on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (49, 4, 'Live It', 'Your Legacy — What You''re Building Beyond Yourself', 'Live It', 'The part of you that carries on past you', 'What do you want to be true because you were here?', 'Stories and identity', '5 of 5', '2, 5, 25, 27', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (49, 'Teen', 4, 'Live It', false, 'Your Legacy — What You''re Building Beyond Yourself', 'What Do You Want Them to Say?', 'There''s an old question: ''What do you want people to say about you when you''re not in the room?'' Not in terms of reputation — but in terms of how you made them feel. That question is the beginning of legacy. Today we answer it.', 'There''s an old question: ''What do you want people to say about you when you''re not in the room?'' Not in terms of reputation — but in terms…', '', '', 'Drop a stone in a pond and the ripples reach edges you''ll never see. Today: name one mark you want rippling out from how you live.', 'Drop a stone in a pond and the ripples reach edges you''ll never see. Today: name one mark you want rippling out from how you live.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (50, 4, 'Live It', 'Gratitude as a Practice, Not a Feeling', 'Live It', 'Noticing specific good things, on purpose', 'What''s good right now that you''d stopped noticing?', 'Signal and attention', '3 of 4', '1, 34, 51', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (50, 'Teen', 4, 'Live It', false, 'Gratitude as a Practice, Not a Feeling', 'Training the Noticing Muscle', 'Here''s what the research actually shows: specific, consistent gratitude practice produces better sleep, lower anxiety, better relationships, and measurably different brain activity. Not as a cure for everything — as a reliable, evidence-based practice for wellbeing. It''s worth doing.', 'Here''s what the research actually shows: specific, consistent gratitude practice produces better sleep, lower anxiety, better relationships, and measurably different brain activity.', '', '', 'Gratitude is a camera — the more you practise pointing it, the more good it finds in frame. Today: capture three specific good moments in words, not generic ones.', 'Gratitude is a camera — the more you practise pointing it, the more good it finds in frame.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (51, 4, 'Live It', 'The Ongoing Practice — There Is No Arrival', 'Live It', 'There''s no finish line, and that''s fine', 'What will you keep doing after this year?', 'Signal and attention', '4 of 4', '1, 34, 50', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (51, 'Teen', 4, 'Live It', false, 'The Ongoing Practice — There Is No Arrival', 'The Journey Is the Point', 'Here''s what the year has taught you: not a formula for being sorted, but a set of practices for being genuinely alive. Those practices don''t end at Week 52. They go with you. They deepen. They become who you are.', 'Here''s what the year has taught you: not a formula for being sorted, but a set of practices for being genuinely alive.', '', '', 'There''s no ''finish line'' notification for growth — the walk is the point. Today: name the one practice you''ll keep for life, arrival or not.', 'There''s no ''finish line'' notification for growth — the walk is the point. Today: name the one practice you''ll keep for life, arrival or not.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (52, 4, 'Live It', 'Integration — A Year of Becoming', 'Live It', 'Pulling the whole year together', 'Who were you a year ago, and what would you tell them?', 'Integration', '4 of 4', '13, 26, 39', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (52, 'Teen', 4, 'Live It', false, 'Integration — A Year of Becoming', 'The Return With Gifts', 'In the oldest stories, the hero''s return is not about arriving home unchanged. It is about arriving home transformed — carrying gifts that were not there at the beginning. You have gifts you didn''t have at Week 1. Today we name them. Together.', 'In the oldest stories, the hero''s return is not about arriving home unchanged.', '', '', 'You''re not closing a book, you''re turning to a blank page with a full backpack and a compass. Today: write the first line of next year''s chapter.', 'You''re not closing a book, you''re turning to a blank page with a full backpack and a compass. Today: write the first line of next year''s chapter.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (1, 1, 'See Clearly', 'The Signal and the Noise', 'See Clearly', 'Noticing what''s going on inside you when everything is noisy', 'What''s something you''ve been thinking about that you haven''t told anyone?', 'Signal and attention', '1 of 4', '34, 50, 51', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (1, 'Child', 1, 'See Clearly', false, 'The Signal and the Noise', 'Finding Your Station', 'Have you ever seen a lighthouse? Even in a really big storm with waves crashing and wind howling, the lighthouse light just keeps going — steady and calm. You have something like that light inside you too.', 'Have you ever seen a lighthouse? Even in a really big storm with waves crashing and wind howling, the lighthouse light just keeps going — steady and calm.', '', '', 'Your mind is a phone with 47 tabs open and notifications firing — the signal is the one tab you opened on purpose. Today: close the tabs (one breath, one thing) and hear the quiet channel underneath the noise.', 'Your mind is a phone with 47 tabs open and notifications firing — the signal is the one tab you opened on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (2, 1, 'See Clearly', 'The Stories We Carry', 'See Clearly', 'The things people say about you, and whether they''re true', 'What do people say you''re like? Is that the whole story?', 'Stories and identity', '1 of 5', '5, 25, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (2, 'Child', 1, 'See Clearly', false, 'The Stories We Carry', 'What''s in Your Backpack?', 'There''s a story about a baby elephant tied to a small post. As a baby it tried to pull free, couldn''t, and eventually stopped trying. Years later, fully grown, the elephant stays next to the tiny post without even pulling. The rope hasn''t changed. The elephant has. We carry stories the same way.', 'There''s a story about a baby elephant tied to a small post. As a baby it tried to pull free, couldn''t, and eventually stopped trying.', '', '', 'The stories you tell about yourself run like an app in the background, quietly draining the battery. Today: catch one ''I''m the kind of person who…'' and ask — did I write this, or did it just install itself?', 'The stories you tell about yourself run like an app in the background, quietly draining the battery.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (3, 1, 'See Clearly', 'The Pattern Interrupt', 'See Clearly', 'The little gap between feeling something and doing something', 'When did you last do something you wished you hadn''t?', 'Choice and response', '1 of 3', '19, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (3, 'Child', 1, 'See Clearly', false, 'The Pattern Interrupt', 'The Pause Button', 'In old stories, the wisest characters — the ones who could solve the hardest problems — were always the ones who could be still. Not frozen. Still. There''s a difference. Stillness is a superpower.', 'In old stories, the wisest characters — the ones who could solve the hardest problems — were always the ones who could be still. Not frozen. Still.', '', '', 'Between the notification buzzing and your hand grabbing the phone there''s a half-second gap — that gap is a superpower. Today: find the buzz-to-grab gap in one habit and slot a single breath into it.', 'Between the notification buzzing and your hand grabbing the phone there''s a half-second gap — that gap is a superpower.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (4, 1, 'See Clearly', 'What Your Body Is Telling You', 'See Clearly', 'What your body tells you before your words do', 'Where do you feel it in your body when you''re worried?', 'The body', '1 of 3', '24, 30', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (4, 'Child', 1, 'See Clearly', false, 'What Your Body Is Telling You', 'Your Feelings Weather Station', 'There''s an old idea that our body, heart, and mind are all connected — like a three-part team. When they''re all working together, we feel strong and good. When one part is ignored, we get wobbly. Today we check in with the whole team.', 'There''s an old idea that our body, heart, and mind are all connected — like a three-part team. When they''re all working together, we feel strong and good.', '', '', 'Your body is the check-engine light your dashboard mind keeps ignoring — tight shoulders and a clenched jaw are data, not noise. Today: do a ten-second body scan before you fire back the stressful message.', 'Your body is the check-engine light your dashboard mind keeps ignoring — tight shoulders and a clenched jaw are data, not noise.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (5, 1, 'See Clearly', 'The Mirror — How We See Ourselves', 'See Clearly', 'Seeing yourself kindly and honestly', 'What''s something you like about yourself?', 'Stories and identity', '2 of 5', '2, 25, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (5, 'Child', 1, 'See Clearly', false, 'The Mirror — How We See Ourselves', 'The True Mirror', 'There''s an old story about a lion cub raised by sheep. It grew up thinking it was a sheep — timid and small. Until one day it saw its reflection in a river and heard a real lion roar. The cub had always been a lion. It just didn''t have the right mirror. You might be missing some things about yourself too.', 'There''s an old story about a lion cub raised by sheep. It grew up thinking it was a sheep — timid and small.', '', '', 'The front camera shows every flaw; a good friend''s photo catches you laughing — self-awareness is choosing the friend''s lens. Today: describe yourself the way someone who loves you would.', 'The front camera shows every flaw; a good friend''s photo catches you laughing — self-awareness is choosing the friend''s lens.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (6, 1, 'See Clearly', 'The Comparison Loop', 'See Clearly', 'Wishing you were like someone else', 'Who do you wish you were more like, and why?', 'Enough', '1 of 3', '20, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (6, 'Child', 1, 'See Clearly', false, 'The Comparison Loop', 'Your Own Puzzle', 'There''s an old idea about flowers: a daisy doesn''t look at a rose and wish it were a rose. A daisy is a perfect daisy. When it tries to be a rose, it forgets to be what it is. You are already your own kind of flower. And that''s brilliant.', 'There''s an old idea about flowers: a daisy doesn''t look at a rose and wish it were a rose. A daisy is a perfect daisy.', '', '', 'Scrolling compares your behind-the-scenes to everyone''s highlight reel — a treadmill where you sweat and never move. Today: name one ''race'' you''re quitting and mute the feed that runs it.', 'Scrolling compares your behind-the-scenes to everyone''s highlight reel — a treadmill where you sweat and never move.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (7, 1, 'See Clearly', 'The Inner Critic', 'See Clearly', 'The unkind voice that says you''re not good enough', 'What does the mean voice in your head say to you?', 'The inner voice', '1 of 3', '18, 32', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (7, 'Child', 1, 'See Clearly', false, 'The Inner Critic', 'Meeting the Gremlin', 'In old stories the wisest characters always had to face a trickster — a creature who tried to confuse them and make them doubt themselves. The trick was always the same: the trickster has no real power once you name him. ''I see you.'' That''s all it takes.', 'In old stories the wisest characters always had to face a trickster — a creature who tried to confuse them and make them doubt themselves.', '', '', 'The inner critic is a group chat in your head that only ever roasts you — you can mute it and add a coach who''s honest but kind. Today: when the roast fires, ask ''would I say this to my best mate?''', 'The inner critic is a group chat in your head that only ever roasts you — you can mute it and add a coach who''s honest but kind.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (8, 1, 'See Clearly', 'Beneath the Surface — Emotions as Data', 'See Clearly', 'The feeling hiding under the big feeling', 'What were you feeling just before you got cross?', 'Emotions as data', '1 of 3', '24, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (8, 'Child', 1, 'See Clearly', false, 'Beneath the Surface — Emotions as Data', 'The Feelings Iceberg', 'There''s an old story about a mother bird who always knew what her babies needed — even before they knew themselves. She didn''t fix it — she listened to the sounds they made. Different sounds meant different things. You are your own mother bird. Your feelings are always making sounds. Today we learn the language.', 'There''s an old story about a mother bird who always knew what her babies needed — even before they knew themselves.', '', '', 'Anger is just the app icon; tap it and the real feeling opens underneath — fear, hurt, tiredness. Today: next time you''re ''grumpy'', open the icon and read what''s actually inside.', 'Anger is just the app icon; tap it and the real feeling opens underneath — fear, hurt, tiredness.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (9, 1, 'See Clearly', 'The Wounds We Carry', 'See Clearly', 'Things that hurt, and telling a safe grown-up', 'What''s something that made you sad that you''ve never said out loud?', 'Old hurt', '1 of 3', '21, 23', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (9, 'Child', 1, 'See Clearly', true, 'The Wounds We Carry', 'The Stone in Your Pocket', 'In old stories the bravest characters were never the ones with no fears or no hurts. They were the ones who knew about their fears — and went anyway. Bravery is not the absence of hurt. Bravery is carrying what''s real and continuing forward.', 'In old stories the bravest characters were never the ones with no fears or no hurts.', '', '', 'Old hurts are a heavy backpack you''ve worn so long you forgot it''s on — naming them in a safe room is setting it down for a minute. Today: name one thing you''ve been carrying, just to feel the weight lift.', 'Old hurts are a heavy backpack you''ve worn so long you forgot it''s on — naming them in a safe room is setting it down for a minute.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (10, 1, 'See Clearly', 'The Masks We Wear', 'See Clearly', 'Pretending to be okay when you''re not', 'When do you pretend you''re fine?', 'Masks and being seen', '1 of 3', '22, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (10, 'Child', 1, 'See Clearly', false, 'The Masks We Wear', 'The Real Face and the Pretend Faces', 'In old stories the greatest friendships and the greatest adventures always started with someone being brave enough to be real — to say ''this is who I actually am.'' The friends who matter always want to know the real you. Today we practise being real.', 'In old stories the greatest friendships and the greatest adventures always started with someone being brave enough to be real — to say ''this is who I actually…', '', '', 'Your profile is the filtered photo; the real you is the whole camera roll — and the right people want the camera roll. Today: show one true, unfiltered thing to someone safe.', 'Your profile is the filtered photo; the real you is the whole camera roll — and the right people want the camera roll.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (11, 1, 'See Clearly', 'Seeing Others Clearly', 'See Clearly', 'What might be going on for someone else', 'Think of someone who was unkind. What might be going on for them?', 'Seeing others', '1 of 3', '44, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (11, 'Child', 1, 'See Clearly', false, 'Seeing Others Clearly', 'Walking Around the Picture', 'In old stories the wisest characters always had the ability to see things from many sides — like a jewel that shimmers differently depending on which angle you hold it at. That wisdom — the ability to really try to understand how things look to someone else — is a skill anyone can learn.', 'In old stories the wisest characters always had the ability to see things from many sides — like a jewel that shimmers differently depending on which angle you…', '', '', 'Everyone''s driving with a dashcam you can''t see — the person who cut you off might be racing to a hospital. Today: give one person the benefit of their unseen story.', 'Everyone''s driving with a dashcam you can''t see — the person who cut you off might be racing to a hospital.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (12, 1, 'See Clearly', 'The Habit Loop — How We Got Here', 'See Clearly', 'The things you do without deciding to', 'What do you always do when you''re upset?', 'Habits and structure', '1 of 4', '29, 33, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (12, 'Child', 1, 'See Clearly', false, 'The Habit Loop — How We Got Here', 'The Habit Path', 'In many old traditions, teachers would ask students: ''What do you do without thinking?'' Not to criticise — but to help them see what had become automatic. Seeing what we do automatically is the beginning of being able to choose. And choice is a superpower.', 'In many old traditions, teachers would ask students: ''What do you do without thinking?'' Not to criticise — but to help them see what had become automatic.', '', '', 'A habit is an autoplay playlist — one trigger and the next track just starts. Today: spot the trigger track for one habit and swap the next song on purpose.', 'A habit is an autoplay playlist — one trigger and the next track just starts.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (13, 1, 'See Clearly', 'Integration — What We Now See', 'See Clearly', 'Looking back at what we''ve noticed', 'What have you found out about yourself this term?', 'Integration', '1 of 4', '26, 39, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (13, 'Child', 1, 'See Clearly', false, 'Integration — What We Now See', 'Looking at Our Full Backpack', 'In every great adventure story there''s a moment where the hero looks back at how far they''ve come before heading towards the next challenge. They don''t usually feel completely different — but they have tools they didn''t have before. Today is that moment.', 'In every great adventure story there''s a moment where the hero looks back at how far they''ve come before heading towards the next challenge.', '', '', 'You''ve been handed a toolkit — a pause button, a feelings-iceberg, a mirror, a mute button for the critic. Today: pick the one tool you''ll actually keep in your pocket.', 'You''ve been handed a toolkit — a pause button, a feelings-iceberg, a mirror, a mute button for the critic.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (14, 2, 'Unlearn', 'The Permission You''re Still Waiting For', 'Unlearn', 'Waiting for someone to say you''re allowed', 'What are you waiting for someone to say yes to?', 'Permission and values', '1 of 4', '15, 28, 43', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (14, 'Child', 2, 'Unlearn', false, 'The Permission You''re Still Waiting For', 'Your Own GO Button', 'There''s an old story about a small bird who refused to fly because nobody had ever told it that it could. One day it fell off a branch — and discovered it had been able to fly all along. You have abilities and ideas waiting for you to discover them. Today we practise leaping.', 'There''s an old story about a small bird who refused to fly because nobody had ever told it that it could.', '', '', 'You keep refreshing an inbox for an approval email that''s never coming — because you''re the one who has to hit send. Today: give yourself the green light on one thing you''ve been waiting on.', 'You keep refreshing an inbox for an approval email that''s never coming — because you''re the one who has to hit send.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (15, 2, 'Unlearn', 'Letting Go of Who You Were Supposed to Be', 'Unlearn', 'Trying to be who everyone expects', 'Who are you trying to make happy?', 'Permission and values', '2 of 4', '14, 28, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (15, 'Child', 2, 'Unlearn', false, 'Letting Go of Who You Were Supposed to Be', 'My Own Picture', 'In old stories, the most interesting characters were never the ones who followed someone else''s map exactly. They were the ones who made their own path — sometimes scary, always more truly theirs. Today we start drawing our own map.', 'In old stories, the most interesting characters were never the ones who followed someone else''s map exactly.', '', '', 'You''ve been reading lines off a teleprompter someone else wrote — but it isn''t your story. Today: put down one ''should'' and say the line that''s actually yours.', 'You''ve been reading lines off a teleprompter someone else wrote — but it isn''t your story. Today: put down one ''should'' and say the line that''s actually yours.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (16, 2, 'Unlearn', 'The Forgiveness Loop', 'Unlearn', 'Staying cross with someone', 'Who are you still cross with?', 'Forgiveness', '1 of 3', '17, 45', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (16, 'Child', 2, 'Unlearn', true, 'The Forgiveness Loop', 'Putting Down the Hot Rock', 'In old stories, the characters who could forgive — not forget, but forgive — were always the strongest ones. Because letting go of a heavy thing takes more courage than holding on to it.', 'In old stories, the characters who could forgive — not forget, but forgive — were always the strongest ones.', '', '', 'Resentment is gripping a hot coal to throw at someone — you''re the one getting burned. Today: name one grudge and picture opening your hand and setting the coal down.', 'Resentment is gripping a hot coal to throw at someone — you''re the one getting burned.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (17, 2, 'Unlearn', 'Forgiving Yourself', 'Unlearn', 'Being kind to yourself when you get it wrong', 'What did you get wrong that you''re still cross with yourself about?', 'Forgiveness', '2 of 3', '16, 45', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (17, 'Child', 2, 'Unlearn', true, 'Forgiving Yourself', 'Say Sorry and Keep Going', 'In old stories, characters who made mistakes had a choice: they could spend the whole story feeling terrible and not trying again — or they could learn, make it right, and keep going. The brave ones always chose to keep going.', 'In old stories, characters who made mistakes had a choice: they could spend the whole story feeling terrible and not trying again — or they could learn, make…', '', '', 'You wouldn''t keep charging a friend for a debt they already paid — so stop billing yourself for the same mistake. Today: mark one thing ''paid — lesson kept'' and close the account.', 'You wouldn''t keep charging a friend for a debt they already paid — so stop billing yourself for the same mistake.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (18, 2, 'Unlearn', 'Rewiring the Critic — Building the Inner Coach', 'Unlearn', 'Swapping the mean voice for a kind, honest one', 'What would a kind coach have said to you instead?', 'The inner voice', '2 of 3', '7, 32', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (18, 'Child', 2, 'Unlearn', false, 'Rewiring the Critic — Building the Inner Coach', 'Making the Kind Voice Louder', 'In stories about heroes, there''s always a wise guide — someone who believes in the hero even when the hero doesn''t believe in themselves. Gandalf. Dumbledore. The cricket from Pinocchio. Today we practise becoming that wise guide for ourselves.', 'In stories about heroes, there''s always a wise guide — someone who believes in the hero even when the hero doesn''t believe in themselves. Gandalf. Dumbledore.', '', '', 'Swap the heckler in your head for a good coach — same honesty, opposite tone. Today: rewrite one harsh line the way a great coach would say it.', 'Swap the heckler in your head for a good coach — same honesty, opposite tone. Today: rewrite one harsh line the way a great coach would say it.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (19, 2, 'Unlearn', 'Breaking the People-Pleasing Pattern', 'Unlearn', 'Saying yes when you meant no', 'When did you say yes when you wanted to say no?', 'Choice and response', '2 of 3', '3, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (19, 'Child', 2, 'Unlearn', false, 'Breaking the People-Pleasing Pattern', 'Kind vs. People-Pleasing', 'In old stories, the characters who tried to make everyone happy all the time usually ended up in trouble — because they kept saying yes when they meant no, until everything got very confusing. The characters who were honest — even when it was uncomfortable — those were usually the ones things worked out for.', 'In old stories, the characters who tried to make everyone happy all the time usually ended up in trouble — because they kept saying yes when they meant…', '', '', 'Saying yes to everything is never closing any apps — your battery hits 1% by noon; a boundary is low-power mode on purpose. Today: turn one fear-''yes'' into an honest ''no''.', 'Saying yes to everything is never closing any apps — your battery hits 1% by noon; a boundary is low-power mode on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (20, 2, 'Unlearn', 'Unlearning Scarcity — There Is Enough', 'Unlearn', 'Worrying there isn''t enough to go around', 'What do you not want to share, and why?', 'Enough', '2 of 3', '6, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (20, 'Child', 2, 'Unlearn', false, 'Unlearning Scarcity — There Is Enough', 'The Things That Don''t Run Out', 'In old stories, there''s often a magic pot or a well that never runs out — no matter how much you take, there''s always more. That sounds like a fairy tale. But there ARE things in your life that don''t run out when you share them. Love. Kindness. Ideas. Laughter. Today we find them.', 'In old stories, there''s often a magic pot or a well that never runs out — no matter how much you take, there''s always more.', '', '', 'Kindness isn''t a biscuit tin that empties — it''s a candle that lights other candles and loses nothing. Today: give something away as if it multiplies, because it does.', 'Kindness isn''t a biscuit tin that empties — it''s a candle that lights other candles and loses nothing.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (21, 2, 'Unlearn', 'The Relationships That Shaped You', 'Unlearn', 'What you learn from the people who look after you', 'What have the grown-ups who look after you taught you about being kind?', 'Old hurt', '2 of 3', '9, 23', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (21, 'Child', 2, 'Unlearn', true, 'The Relationships That Shaped You', 'The Gifts People Give Us', 'In old stories there are always the wise elders — people whose influence stays with the hero long after they''ve parted. The hero carries what was good and leaves behind what wasn''t theirs to carry. Today we think about who has been our wise elder — and what they gave us.', 'In old stories there are always the wise elders — people whose influence stays with the hero long after they''ve parted.', '', '', 'You inherited relationship ''settings'' the way a phone ships with defaults — some are great, some need updating. Today: spot one default about love you want to change.', 'You inherited relationship ''settings'' the way a phone ships with defaults — some are great, some need updating. Today: spot one default about love you want to change.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (22, 2, 'Unlearn', 'Setting Down the Armour', 'Unlearn', 'The walls we put up to feel safe', 'When do you go quiet so nobody can see you''re upset?', 'Masks and being seen', '2 of 3', '10, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (22, 'Child', 2, 'Unlearn', false, 'Setting Down the Armour', 'The Shield With a Door', 'In old stories, the heroes always had a shield — but the wisest ones knew when to use it and when to set it aside. A shield you never put down stops being protection and starts being a wall. And walls keep out friends as well as danger.', 'In old stories, the heroes always had a shield — but the wisest ones knew when to use it and when to set it aside.', '', '', 'The armour that got you through school now sets off the metal detector at the hug. Today: lower one piece of armour — sarcasm, busyness, control — with one safe person.', 'The armour that got you through school now sets off the metal detector at the hug.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (23, 2, 'Unlearn', 'Grief and Growth — What Endings Make Possible', 'Unlearn', 'When something ends', 'What have you lost that you still miss?', 'Old hurt', '3 of 3', '9, 21', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (23, 'Child', 2, 'Unlearn', true, 'Grief and Growth — What Endings Make Possible', 'The Autumn Before Spring', 'In old stories, even the saddest moments always led somewhere. Not immediately. Not easily. But the saddest chapter was never the last chapter. Today we learn to trust that — even when it doesn''t feel true yet.', 'In old stories, even the saddest moments always led somewhere. Not immediately. Not easily. But the saddest chapter was never the last chapter.', '', '', 'Winter looks like the tree died, but it''s just clearing the branches for spring. Today: name what an ending has quietly made room for.', 'Winter looks like the tree died, but it''s just clearing the branches for spring. Today: name what an ending has quietly made room for.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (24, 2, 'Unlearn', 'Rewiring Fear — From Threat to Signal', 'Unlearn', 'Being scared, and what fear is telling you', 'What are you scared of that has never actually happened?', 'The body', '2 of 3', '4, 30', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (24, 'Child', 2, 'Unlearn', true, 'Rewiring Fear — From Threat to Signal', 'The Toast Alarm vs. The Real Fire', 'In old stories, the bravest heroes weren''t the ones who were never scared. They were the ones who felt scared AND kept going anyway. Because they learned that most scary things, once you face them, turn out to be much more manageable than they looked from far away.', 'In old stories, the bravest heroes weren''t the ones who were never scared. They were the ones who felt scared AND kept going anyway.', '', '', 'Most alarms in your head are burnt toast, not a house fire — the smoke detector just can''t tell the difference. Today: label one fear ''burnt toast'' and open a window instead of running.', 'Most alarms in your head are burnt toast, not a house fire — the smoke detector just can''t tell the difference.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (25, 2, 'Unlearn', 'The Stories That No Longer Serve', 'Unlearn', 'An old story about yourself that isn''t true any more', 'What did you used to believe about yourself that isn''t true now?', 'Stories and identity', '3 of 5', '2, 5, 27, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (25, 'Child', 2, 'Unlearn', false, 'The Stories That No Longer Serve', 'Updating the Photo Album', 'In old stories, the characters who grew the most were always the ones who were brave enough to see themselves differently — to say ''I am not just the same as I was. I have grown. I have changed. I am more than the old story.'' Today we practise that bravery.', 'In old stories, the characters who grew the most were always the ones who were brave enough to see themselves differently — to say ''I am not just…', '', '', 'An old story is a saved route on your maps app that no longer goes where you live. Today: delete one outdated ''I always…'' and set a new destination.', 'An old story is a saved route on your maps app that no longer goes where you live.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (26, 2, 'Unlearn', 'Integration — What We Have Released', 'Unlearn', 'Looking back at what we''ve put down', 'What have you let go of this term?', 'Integration', '2 of 4', '13, 39, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (26, 'Child', 2, 'Unlearn', false, 'Integration — What We Have Released', 'Putting Down the Heavy Things', 'In old adventure stories, there''s always a moment between battles — a camp, a rest, a celebration. The heroes look at each other and say ''we made it through.'' Not because the adventure is over — but because this part is done. And they''re stronger for it. Today is that moment.', 'In old adventure stories, there''s always a moment between battles — a camp, a rest, a celebration.', '', '', 'You''ve cleared a pile of old apps clogging the phone — permission-seeking, resentment, armour. Today: notice how much lighter and faster you run without them.', 'You''ve cleared a pile of old apps clogging the phone — permission-seeking, resentment, armour. Today: notice how much lighter and faster you run without them.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (27, 3, 'Rebuild', 'Who Are You Now? — Rebuilding Identity', 'Rebuild', 'Choosing who you want to be', 'Who do you want to be?', 'Stories and identity', '4 of 5', '2, 5, 25, 49', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (27, 'Child', 3, 'Rebuild', false, 'Who Are You Now? — Rebuilding Identity', 'Who Are You Building?', 'In building stories, the best heroes are always the ones who discover who they truly are — not because someone told them, but because they chose it. Chose their values, chose their courage, chose their kindness. Today we start choosing.', 'In building stories, the best heroes are always the ones who discover who they truly are — not because someone told them, but because they chose it.', '', '', 'Instead of the labels stuck on you like airport baggage tags, you get to pack your own bag. Today: choose the three qualities you''re building yourself from.', 'Instead of the labels stuck on you like airport baggage tags, you get to pack your own bag. Today: choose the three qualities you''re building yourself from.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (28, 3, 'Rebuild', 'What Do You Actually Value?', 'Rebuild', 'What matters most to you', 'What''s the most important thing to you?', 'Permission and values', '3 of 4', '14, 15, 43', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (28, 'Child', 3, 'Rebuild', false, 'What Do You Actually Value?', 'Your Inner Compass', 'In old stories, the bravest heroes always had a strong inner compass — they knew what mattered, and they stuck to it even when things got hard. That compass was their values. Today we discover ours.', 'In old stories, the bravest heroes always had a strong inner compass — they knew what mattered, and they stuck to it even when things got hard.', '', '', 'Values are your GPS ''home'' setting — every turn is easier once it''s locked in. Today: name your true-north value and check one recent decision against it.', 'Values are your GPS ''home'' setting — every turn is easier once it''s locked in. Today: name your true-north value and check one recent decision against it.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (29, 3, 'Rebuild', 'The Habits That Build You', 'Rebuild', 'Small things you do every day', 'What do you do every day that makes you a bit better at something?', 'Habits and structure', '2 of 4', '12, 33, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (29, 'Child', 3, 'Rebuild', false, 'The Habits That Build You', 'Watering Your Garden', 'In old stories about people who became truly great — kind, wise, brave, skilled — it was never from one magic moment. It was always from small, consistent practice. Every single day. A little bit. That''s how greatness actually grows.', 'In old stories about people who became truly great — kind, wise, brave, skilled — it was never from one magic moment.', '', '', 'You don''t get fit from one epic gym session — you get fit from showing up small and often; identity works the same. Today: pick the 1% habit you''ll repeat like brushing your teeth.', 'You don''t get fit from one epic gym session — you get fit from showing up small and often; identity works the same.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (30, 3, 'Rebuild', 'Your Body as Foundation', 'Rebuild', 'Sleep, food, moving, resting', 'What does your body need more of?', 'The body', '3 of 3', '4, 24', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (30, 'Child', 3, 'Rebuild', false, 'Your Body as Foundation', 'Charging Your Superhero Suit', 'Ancient peoples knew something important: a well-rested, well-moved, well-nourished body thinks more clearly, feels more balanced, and has more courage. They were right — and now science confirms it. Today we learn the four things that charge our superhero suit.', 'Ancient peoples knew something important: a well-rested, well-moved, well-nourished body thinks more clearly, feels more balanced, and has more courage.', '', '', 'Your body is the phone the whole day runs on, and sleep, movement, food and calm are the four charging cables. Today: plug in the one that''s most drained.', 'Your body is the phone the whole day runs on, and sleep, movement, food and calm are the four charging cables.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (31, 3, 'Rebuild', 'The People You Choose', 'Rebuild', 'The people you spend time with', 'Who makes you feel like yourself?', 'Belonging', '1 of 3', '38, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (31, 'Child', 3, 'Rebuild', false, 'The People You Choose', 'Growing Friends', 'In old stories the best companions were always the ones who brought out the best in the hero — who believed in them, told them the truth, and stood by them through hard times. That kind of friendship is worth finding AND worth being. Today we think about both.', 'In old stories the best companions were always the ones who brought out the best in the hero — who believed in them, told them the truth, and…', '', '', 'You become the average of your five most-opened contacts. Today: pick one relationship to open more, and one notification to turn down.', 'You become the average of your five most-opened contacts. Today: pick one relationship to open more, and one notification to turn down.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (32, 3, 'Rebuild', 'How You Speak to Yourself', 'Rebuild', 'How you talk to yourself', 'What would you say to a friend who was where you are?', 'The inner voice', '3 of 3', '7, 18', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (32, 'Child', 3, 'Rebuild', false, 'How You Speak to Yourself', 'Finding Your Power Phrases', 'In old stories, the bravest characters would say something to themselves before a challenge — a promise to themselves, a reminder of who they were. Those words became their power. Today we find ours.', 'In old stories, the bravest characters would say something to themselves before a challenge — a promise to themselves, a reminder of who they were.', '', '', 'Talk to yourself like you''d text a friend having a hard day — not like an anonymous troll in the comments. Today: keep one kind phrase in your pocket for the next hard moment.', 'Talk to yourself like you''d text a friend having a hard day — not like an anonymous troll in the comments.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (33, 3, 'Rebuild', 'Creating Structure That Serves You', 'Rebuild', 'Having a rhythm to your week', 'What part of your week do you look forward to?', 'Habits and structure', '3 of 4', '12, 29, 47', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (33, 'Child', 3, 'Rebuild', false, 'Creating Structure That Serves You', 'Your Personal Rhythm', 'In old stories, the wisest people always had a rhythm to their days — they knew when to work, when to rest, when to play, and when to think. That rhythm didn''t make their days boring. It made everything else possible.', 'In old stories, the wisest people always had a rhythm to their days — they knew when to work, when to rest, when to play, and when to…', '', '', 'Routine isn''t a cage — it''s the trellis a plant climbs to reach the light. Today: add one small anchor (same wake time, one blocked hour) and let freedom grow on it.', 'Routine isn''t a cage — it''s the trellis a plant climbs to reach the light.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (34, 3, 'Rebuild', 'Rest as a Practice, Not a Reward', 'Rebuild', 'Resting without having to earn it', 'When do you feel properly rested?', 'Signal and attention', '2 of 4', '1, 50, 51', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (34, 'Child', 3, 'Rebuild', false, 'Rest as a Practice, Not a Reward', 'Rest Is a Superpower', 'In old stories, even the greatest heroes had to rest before the big challenge. Not because they were weak — but because they were wise enough to know that the body and mind need recovery time to do their best. Rest is a superpower, not a sign of being lazy.', 'In old stories, even the greatest heroes had to rest before the big challenge.', '', '', 'You plug your phone in before it dies, not after — do the same for yourself. Today: schedule one real rest block before you''re down to 1%.', 'You plug your phone in before it dies, not after — do the same for yourself. Today: schedule one real rest block before you''re down to 1%.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (35, 3, 'Rebuild', 'Creativity and Expression', 'Rebuild', 'Making things just because you like it', 'What do you love making?', 'Creativity and expression', '1 of 3', '41, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (35, 'Child', 3, 'Rebuild', false, 'Creativity and Expression', 'The Joy of Making', 'The most creative people in history — inventors, artists, storytellers — all had one thing in common: they were willing to make things that weren''t perfect. In fact, most of their greatest creations came out of lots of imperfect attempts. Today we celebrate the imperfect making.', 'The most creative people in history — inventors, artists, storytellers — all had one thing in common: they were willing to make things that weren''t perfect.', '', '', 'Making something is like cooking for yourself — it doesn''t need a Michelin star to feed you. Today: make one small thing no one will grade.', 'Making something is like cooking for yourself — it doesn''t need a Michelin star to feed you. Today: make one small thing no one will grade.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (36, 3, 'Rebuild', 'Purpose — What You''re Here For', 'Rebuild', 'What you''re good at and what people need', 'What are you doing when you forget about time?', 'Purpose', '1 of 3', '40, 49', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (36, 'Child', 3, 'Rebuild', false, 'Purpose — What You''re Here For', 'Your Special Puzzle Piece', 'In old stories about heroes and great people, they always had something special — a gift that was uniquely theirs. Not perfect. Not magical. Just genuinely theirs. And they used it to make things better. Today we find yours.', 'In old stories about heroes and great people, they always had something special — a gift that was uniquely theirs. Not perfect. Not magical. Just genuinely theirs.', '', '', 'Purpose is where your skills and the world''s needs overlap — the sweet spot of the Venn diagram. Today: name one small place that overlap already exists.', 'Purpose is where your skills and the world''s needs overlap — the sweet spot of the Venn diagram. Today: name one small place that overlap already exists.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (37, 3, 'Rebuild', 'Money, Abundance and Your Relationship With Resources', 'Rebuild', 'What money is for', 'What would you do with ten dollars, and why?', 'Resources', '2 of 3', '20, 46', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (37, 'Child', 3, 'Rebuild', false, 'Money, Abundance and Your Relationship With Resources', 'What We Have and What We Share', 'In old stories, the happiest and wisest characters were never the ones who had the most things. They were the ones who valued what they had, shared generously, and knew the difference between what they needed and what they just wanted. Today we learn that wisdom.', 'In old stories, the happiest and wisest characters were never the ones who had the most things.', '', '', 'Your money ''scripts'' are inherited apps running in the background of every purchase. Today: sort one thing into need / want / could-share and notice which script ran.', 'Your money ''scripts'' are inherited apps running in the background of every purchase. Today: sort one thing into need / want / could-share and notice which script ran.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (38, 3, 'Rebuild', 'The Community You Build', 'Rebuild', 'Being part of something together', 'What do you bring to a group?', 'Belonging', '2 of 3', '31, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (38, 'Child', 3, 'Rebuild', false, 'The Community You Build', 'Being Part of Something Bigger', 'In old stories, the strongest characters were always the ones who had good communities around them — people who cared, who helped, who showed up. And the strongest characters were also the ones who gave back — who contributed something that made their community better. Today we think about both.', 'In old stories, the strongest characters were always the ones who had good communities around them — people who cared, who helped, who showed up.', '', '', 'A community is a beehive — it works because everyone brings something back. Today: name the one thing you''ll bring to a room you want to belong to.', 'A community is a beehive — it works because everyone brings something back. Today: name the one thing you''ll bring to a room you want to belong to.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (39, 3, 'Rebuild', 'Integration — Who You Are Becoming', 'Rebuild', 'Looking back at who you''re becoming', 'What''s different about you now?', 'Integration', '3 of 4', '13, 26, 52', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (39, 'Child', 3, 'Rebuild', false, 'Integration — Who You Are Becoming', 'Look What We''ve Built!', 'In adventure stories, there always comes the moment when the hero has done the training, learned the skills, found their team — and it''s time to go. Not because they''re perfect. Because they''re ready enough, and the world needs what they have. Today is that moment.', 'In adventure stories, there always comes the moment when the hero has done the training, learned the skills, found their team — and it''s time to go.', '', '', 'The building site is now a home you can live in — identity, values, habits, people. Today: name who you''ve become, and step through the door into living it.', 'The building site is now a home you can live in — identity, values, habits, people.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (40, 4, 'Live It', 'From Self-Development to Service', 'Live It', 'Using what you''ve learned to help someone', 'Who could you help this week?', 'Purpose', '2 of 3', '36, 49', 'Movement opener') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (40, 'Child', 4, 'Live It', false, 'From Self-Development to Service', 'Sharing the Treasure', 'In old stories, the hero''s journey always ended the same way — not with the hero keeping all the treasure for themselves, but with them returning home and sharing it. The return and the sharing is the most important part. Today we begin our return.', 'In old stories, the hero''s journey always ended the same way — not with the hero keeping all the treasure for themselves, but with them returning home and…', '', '', 'You don''t hoard the wifi password once you''re connected — you share it; inner work is the same. Today: give one thing you''ve healed enough to offer someone else.', 'You don''t hoard the wifi password once you''re connected — you share it; inner work is the same.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (41, 4, 'Live It', 'Teaching What You''ve Learned', 'Live It', 'Teaching someone what you know', 'What could you teach someone younger than you?', 'Creativity and expression', '2 of 3', '35, 42', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (41, 'Child', 4, 'Live It', false, 'Teaching What You''ve Learned', 'Becoming a Teacher', 'In old stories, wisdom was always passed on — from elder to young, from those who''d learned to those just beginning. Today we practise that. You have wisdom to pass on. More than you know.', 'In old stories, wisdom was always passed on — from elder to young, from those who''d learned to those just beginning. Today we practise that.', '', '', 'Explaining something to a ten-year-old is how you find out you actually understand it. Today: put one lesson into one plain sentence and pass it on.', 'Explaining something to a ten-year-old is how you find out you actually understand it. Today: put one lesson into one plain sentence and pass it on.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (42, 4, 'Live It', 'The Courage to Be Seen', 'Live It', 'Letting people see the real you', 'What''s something true about you that you keep hidden?', 'Masks and being seen', '3 of 3', '10, 22', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (42, 'Child', 4, 'Live It', true, 'The Courage to Be Seen', 'The Real You, All the Way', 'The bravest thing in old stories was never fighting a dragon. It was being honest — truly honest — about who you are, even when that felt scary. Because the truest connections happen when people see the real you and choose to be close to you anyway.', 'The bravest thing in old stories was never fighting a dragon. It was being honest — truly honest — about who you are, even when that felt scary.', '', '', 'Turning your camera on in the meeting is scary for two seconds and connecting for the rest. Today: show up ''camera-on'' in one place you usually hide.', 'Turning your camera on in the meeting is scary for two seconds and connecting for the rest. Today: show up ''camera-on'' in one place you usually hide.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (43, 4, 'Live It', 'Living Your Values Under Pressure', 'Live It', 'Doing the right thing when it''s hard', 'When is it hardest to do the right thing?', 'Emotions as data', '3 of 3', '8, 24', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (43, 'Child', 4, 'Live It', false, 'Living Your Values Under Pressure', 'Compass in the Storm', 'In old stories, the characters who were truly brave were never the ones who did the right thing only when it was easy. They were the ones who did the right thing even when it was hard. That''s real courage. Today we practise it.', 'In old stories, the characters who were truly brave were never the ones who did the right thing only when it was easy.', '', '', 'Your values are only real in the storm, not the sunshine — like a compass that has to work when the sky goes dark. Today: name one value you''ll hold even when it costs you.', 'Your values are only real in the storm, not the sunshine — like a compass that has to work when the sky goes dark.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (44, 4, 'Live It', 'Conflict as a Growth Practice', 'Live It', 'Sorting out a fight instead of walking away', 'What argument do you need to sort out?', 'Seeing others', '2 of 3', '11, 48', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (44, 'Child', 4, 'Live It', false, 'Conflict as a Growth Practice', 'The Gentle Untangle', 'In old stories, the wisest characters were always the ones who could find a way through a conflict without destroying what mattered. Not by giving up what they needed — but by finding out what the other person needed too. Today we practise that wisdom.', 'In old stories, the wisest characters were always the ones who could find a way through a conflict without destroying what mattered.', '', '', '''You always…'' starts a fight; ''I feel… I need…'' starts a conversation. Today: rewrite one hard message in the second language.', '''You always…'' starts a fight; ''I feel… I need…'' starts a conversation. Today: rewrite one hard message in the second language.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (45, 4, 'Live It', 'Generosity as a Way of Being', 'Live It', 'Giving in a way that feels good', 'What can you give that doesn''t cost anything?', 'Forgiveness', '3 of 3', '16, 17', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (45, 'Child', 4, 'Live It', false, 'Generosity as a Way of Being', 'Gifts That Grow', 'In old stories, the most beloved characters were never the ones with the most treasures. They were the ones who shared freely — their time, their kindness, their help. Because those gifts grow when you give them away.', 'In old stories, the most beloved characters were never the ones with the most treasures.', '', '', 'Some gifts — encouragement, time, attention — cost nothing and still glow in your own hands after you give them. Today: give one non-money gift by Sunday.', 'Some gifts — encouragement, time, attention — cost nothing and still glow in your own hands after you give them. Today: give one non-money gift by Sunday.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (46, 4, 'Live It', 'Enough — Living From Sufficiency', 'Live It', 'Noticing what''s already good', 'What''s already good that you''d stopped noticing?', 'Enough', '3 of 3', '6, 20', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (46, 'Child', 4, 'Live It', false, 'Enough — Living From Sufficiency', 'Noticing the Garden', 'There''s an old story about a child who spent so long looking at the horizon for something they were waiting for, they missed the beautiful garden they were standing in. Today we notice our garden.', 'There''s an old story about a child who spent so long looking at the horizon for something they were waiting for, they missed the beautiful garden they were…', '', '', 'The ''add to cart'' feeling is a treadmill — one more thing never becomes enough. Today: name three things you already have that are genuinely enough.', 'The ''add to cart'' feeling is a treadmill — one more thing never becomes enough. Today: name three things you already have that are genuinely enough.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (47, 4, 'Live It', 'The Long Game — Patience and Persistence', 'Live It', 'Keeping going when nothing looks different yet', 'What are you practising that''s still hard?', 'Habits and structure', '4 of 4', '12, 29, 33', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (47, 'Child', 4, 'Live It', false, 'The Long Game — Patience and Persistence', 'Keep Watering the Plant', 'In old stories, the heroes who achieved the most extraordinary things were never the ones who gave up when it was hard. They were the ones who kept going — day after day — even when they couldn''t see the progress. Today we celebrate that kind of perseverance.', 'In old stories, the heroes who achieved the most extraordinary things were never the ones who gave up when it was hard.', '', '', 'A seed spends weeks looking like nothing while it grows roots — don''t dig it up to check. Today: recommit to one slow, unglamorous thing that''s still growing underground.', 'A seed spends weeks looking like nothing while it grows roots — don''t dig it up to check.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (48, 4, 'Live It', 'Leaving People Better Than You Found Them', 'Live It', 'Leaving people happier than you found them', 'Who made you feel good this week, and how?', 'Seeing others', '3 of 3', '11, 44', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (48, 'Child', 4, 'Live It', false, 'Leaving People Better Than You Found Them', 'Being a Sunshine Person', 'In old stories, the most beloved characters were never the ones who did the most dramatic things. They were the ones who made every person they met feel seen, valued, and cared for. Today we practise that.', 'In old stories, the most beloved characters were never the ones who did the most dramatic things.', '', '', 'You leave a ''tip'' in every interaction — a little brighter or a little dimmer. Today: leave one person brighter, on purpose.', 'You leave a ''tip'' in every interaction — a little brighter or a little dimmer. Today: leave one person brighter, on purpose.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (49, 4, 'Live It', 'Your Legacy — What You''re Building Beyond Yourself', 'Live It', 'The good you leave behind you', 'What do you want people to remember about you?', 'Stories and identity', '5 of 5', '2, 5, 25, 27', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (49, 'Child', 4, 'Live It', false, 'Your Legacy — What You''re Building Beyond Yourself', 'Your Ripples', 'In old stories, the characters who were remembered most fondly were never the ones who were most powerful or most famous. They were the ones who made others feel most loved, most seen, most capable. Today we think about that kind of mark.', 'In old stories, the characters who were remembered most fondly were never the ones who were most powerful or most famous.', '', '', 'Drop a stone in a pond and the ripples reach edges you''ll never see. Today: name one mark you want rippling out from how you live.', 'Drop a stone in a pond and the ripples reach edges you''ll never see. Today: name one mark you want rippling out from how you live.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (50, 4, 'Live It', 'Gratitude as a Practice, Not a Feeling', 'Live It', 'Noticing good things on purpose', 'What three good things happened today?', 'Signal and attention', '3 of 4', '1, 34, 51', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (50, 'Child', 4, 'Live It', false, 'Gratitude as a Practice, Not a Feeling', 'Training the Gratitude Camera', 'In old traditions, wise people always had a practice of thankfulness — every morning, every evening — not because life was always wonderful, but because noticing the good things kept their hearts open and their spirits strong. Today we build that practice.', 'In old traditions, wise people always had a practice of thankfulness — every morning, every evening — not because life was always wonderful, but because noticing the good…', '', '', 'Gratitude is a camera — the more you practise pointing it, the more good it finds in frame. Today: capture three specific good moments in words, not generic ones.', 'Gratitude is a camera — the more you practise pointing it, the more good it finds in frame.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (51, 4, 'Live It', 'The Ongoing Practice — There Is No Arrival', 'Live It', 'You never finish growing', 'What will you keep practising?', 'Signal and attention', '4 of 4', '1, 34, 50', 'Standard') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (51, 'Child', 4, 'Live It', false, 'The Ongoing Practice — There Is No Arrival', 'The Adventure Continues', 'In old stories, the hero''s journey doesn''t end when they return home. It becomes the rest of their life — richer, deeper, more alive because of everything they''ve been through. Today we begin the rest of our story.', 'In old stories, the hero''s journey doesn''t end when they return home.', '', '', 'There''s no ''finish line'' notification for growth — the walk is the point. Today: name the one practice you''ll keep for life, arrival or not.', 'There''s no ''finish line'' notification for growth — the walk is the point. Today: name the one practice you''ll keep for life, arrival or not.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
INSERT INTO public.curriculum_weeks (week_number, block_number, block_theme, weekly_theme, movement_theme, the_territory, opening_question, spiral_thread, spiral_depth, revisits_weeks, week_type) VALUES (52, 4, 'Live It', 'Integration — A Year of Becoming', 'Live It', 'Looking back at the whole year', 'What can you do now that you couldn''t a year ago?', 'Integration', '4 of 4', '13, 26, 39', 'Integration') ON CONFLICT (week_number) DO UPDATE SET block_number = EXCLUDED.block_number, block_theme = EXCLUDED.block_theme, weekly_theme = EXCLUDED.weekly_theme, movement_theme = EXCLUDED.movement_theme, the_territory = EXCLUDED.the_territory, opening_question = EXCLUDED.opening_question, spiral_thread = EXCLUDED.spiral_thread, spiral_depth = EXCLUDED.spiral_depth, revisits_weeks = EXCLUDED.revisits_weeks, week_type = EXCLUDED.week_type;
INSERT INTO public.mindcast_live_sessions (week_number, audience, phase, phase_name, heavy_week_flag, theme_title, session_title, ancient_wisdom_reframe, ancient_wisdom_vo_script, ancient_wisdom_video_url, ancient_wisdom_captions_url, signal_metaphor, todays_world_vo_script, todays_world_video_url, todays_world_captions_url, todays_theme, s5_source_opening_hook, s5_source_core_concept, video_link, video_description, video_transcript, video_question_1, video_question_2, private_write_prompt, experiential_exercise, journaling_prompt, intention_prompt, weekly_practice_mon, weekly_practice_wed, weekly_practice_sun, closing_quote, closing_quote_attribution, core_affirmation, facilitator_prep_notes, watch_for, first_time_note, previous_week_callback) VALUES (52, 'Child', 4, 'Live It', false, 'Integration — A Year of Becoming', 'The Best Kind of Ending', 'In all the best stories, the end is really the beginning — the hero returns home changed, ready for the real adventure. Today we arrive at that moment together. Changed. Ready. Beginning.', 'In all the best stories, the end is really the beginning — the hero returns home changed, ready for the real adventure.', '', '', 'You''re not closing a book, you''re turning to a blank page with a full backpack and a compass. Today: write the first line of next year''s chapter.', 'You''re not closing a book, you''re turning to a blank page with a full backpack and a compass. Today: write the first line of next year''s chapter.', '', '', 'DRAFT — rewrite from the video transcript once the video is chosen.
